typedef enum {
    JS_GC_PHASE_NONE,
    JS_GC_PHASE_DECREF,
    JS_GC_PHASE_REMOVE_CYCLES,
} JSGCPhaseEnum;

typedef struct JSMallocState {
    size_t malloc_count;
    size_t malloc_size;
    size_t malloc_limit;
    void *opaque; /* user opaque */
} JSMallocState;

/* Small-block "arena" allocator.
   js_{malloc,free,realloc,calloc}_rt serve allocations up to ~512
   bytes from size-classed 4KB arenas carved out of the underlying
   JSMallocFunctions allocator, so the backing allocator (system malloc,
   mimalloc, ...) sees roughly one request per arena refill instead of one per
   object. */

#define JS_ARENA_ALIGN             8
#define JS_ARENA_SIZE              4096
#define JS_ARENA_BLOCK_SIZE_COUNT  31
#define JS_ARENA_MAX_SMALL_SIZE    512
#define JS_ARENA_FREE_NIL          0xffff

#if defined(__SANITIZE_ADDRESS__) || defined(FORCE_GC_AT_MALLOC)
/* Route every allocation through the backing malloc so each block is seen
   individually: ASan can then poison a freed block, and a GC-stress build
   (FORCE_GC_AT_MALLOC) exposes prematurely-freed objects instead of the pool
   silently recycling them. */
#define JS_ARENA_LARGE_BLOCKS_ONLY 1
#else
#define JS_ARENA_LARGE_BLOCKS_ONLY 0
#endif

/* 8-byte header preceding every user allocation. It carries the allocator
   bookkeeping (block_idx/free_next + block_size_idx) and, the
   GC/refcount fields (gc_obj_type/mark/ref_count) that would otherwise sit in
   the object body. The 8-byte size keeps user_data JS_ARENA_ALIGN-aligned. */
typedef struct JSMallocBlockHeader {
    union {
        uint16_t block_idx;   /* JS_ARENA_FREE_NIL => large or zero-size block */
        uint16_t free_next;   /* next free block index while on a free list */
    } u;
    uint8_t  block_size_idx;
    /* GC/refcount header merged into the allocator header:
       the object body keeps only JSGCObjectHeader.link (no ref_count/flags). */
    uint8_t  gc_obj_type : 7; /* JSGCObjectTypeEnum for GC objects */
    uint8_t  mark : 1;        /* used by the cycle collector */
    int      ref_count;
    _Alignas(JS_ARENA_ALIGN) uint8_t user_data[];
} JSMallocBlockHeader;

typedef struct JSArena {
    struct list_head free_link;   /* in free_arena_list[idx] while not full */
    struct list_head link;        /* in arena_list[idx] for the whole lifetime */
    uint8_t  block_size_idx;
    uint16_t n_used_blocks;
    uint16_t n_blocks;
    uint16_t first_free_block;    /* JS_ARENA_FREE_NIL if none */
    _Alignas(JS_ARENA_ALIGN) uint8_t blocks[];
} JSArena;

typedef struct JSArenaState {
    struct list_head arena_list[JS_ARENA_BLOCK_SIZE_COUNT];
    struct list_head free_arena_list[JS_ARENA_BLOCK_SIZE_COUNT];
    _Alignas(JS_ARENA_ALIGN) uint8_t zero_size_block[sizeof(JSMallocBlockHeader)];
} JSArenaState;

typedef struct JSRuntimeFinalizerState {
    struct JSRuntimeFinalizerState *next;
    JSRuntimeFinalizer *finalizer;
    void *arg;
} JSRuntimeFinalizerState;

typedef struct JSValueLink {
    struct JSValueLink *next;
    JSValueConst value;
} JSValueLink;

typedef struct JSTrampStepDef JSTrampStepDef;   /* quickjs-step.h, included below with the rest of the surface */
/* The spec algorithm a step def names, for the two abort paths that must report one. js_call_c_function_data's
   backstop belongs beside the closure constructor, which is thousands of lines ABOVE that include, so the struct
   is still incomplete there and the field is reached through this rather than by widening the forward
   declaration. Dev-only, because the only caller is dev-only: an abort path formats nothing in release. */
#if APICLIENT_DEV
static const char *js_step_def_algorithm(const JSTrampStepDef *def);
#endif
struct JSRuntime {
    /* HOST-REGISTERED STEP MACHINES. JS_CFUNC_STEP_DEF names its machine by an id; the built-in ids index a
       static table and a host component's id continues past STEPDEF_COUNT into this array. It is on the RUNTIME
       because a definition belongs to the engine instance that was told about it, and because the def POINTER
       cannot ride the function object — JSCFunctionType holds function pointers, and putting data in it is the
       strict-aliasing violation that segfaulted a whole directory at -O1. The id is the indirection.
       Every tramp_step_def_by_id call site names a built-in id literally, so only the lookup that starts from a
       CALLEE needs to reach this — and that one has the object, hence the runtime. */
    const JSTrampStepDef **host_step_defs;
    int host_step_def_count;
    /* HOW MANY FUNCTION OBJECTS THIS RUNTIME HAS EVER MADE — bumped at js_closure2, which is the one line every
       one of them passes through, and read by JS_OrphanGen. It is not a statistic: it is the exact answer to
       "could the orphan set have grown since I last looked", because creating a function object is the only
       event that can add to it. A host takes the orphans when this number has moved and skips the heap walk
       when it has not. Wraps at 2^32 as a MONOTONE COUNTER is entitled to — a host compares it for INEQUALITY
       only, so a wrap costs one redundant walk and never a skipped one. */
    uint32_t orphan_gen;
    JSMallocFunctions mf;
    JSMallocState malloc_state;
    JSArenaState arena_state;
    const char *rt_info;

    int atom_hash_size; /* power of two */
    int atom_count;
    int atom_size;
    int atom_count_resize; /* resize hash table at this count */
    uint32_t *atom_hash;
    JSAtomStruct **atom_array;
    int atom_free_index; /* 0 = none */

    JSClassID js_class_id_alloc; /* counter for user defined classes */
    int class_count;    /* size of class_array */
    JSClass *class_array;

    struct list_head context_list; /* list of JSContext.link */
    /* EVERY LIVE STEP MACHINE — see JSStepHdr.census_prev. gc_obj_list below is this list's model and its
       reason: a GC object the runtime drops is named at teardown, and until this existed a step state was the
       one allocation the engine makes that nothing counted. It is intrusive and unconditional for the same
       reason gc_obj_list is — a leak report that exists only in some builds reports only some leaks. */
    struct JSStepHdr *step_census;
    int step_census_n;
    /* JS_StepVisitOwnedFingerprint's accumulator. It lives on the RUNTIME rather than in a file static because
       a file static is one number for however many corpus threads the harness runs, and the two healthy
       runtimes would then fold into each other's answer — the same defect that made g_tramp_frames_live's
       unwound-chain DCHECK fire on a race between two healthy threads. One runtime is one thread's, so this
       is the narrowest place the accumulator can live and still be reachable from a visit operation, which is
       handed nothing but a slot. */
    uint64_t step_owned_fp;
    /* list of JSGCObjectHeader.link. List of allocated GC objects (used
       by the garbage collector) */
    struct list_head gc_obj_list;
    /* list of JSGCObjectHeader.link. Used during JS_FreeValueRT() */
    struct list_head gc_zero_ref_count_list;
    struct list_head tmp_obj_list; /* used during GC */
    /* THE OBJECT WHOSE CHILDREN THE DECREF PASS IS WALKING. gc_decref_child is a JS_MarkFunc, so it is handed
       a CHILD and nothing else — and the edge being walked belongs to the PARENT, which is where a mark with
       no reference behind it is written. Every gc_mark in this engine reaches that one line, so the abort
       there named an address no reader could use: an assert that names a remedy and not a site is a crash
       nobody can act on, and the site here is an object rather than a file and line. It lives on the RUNTIME
       for the reason step_owned_fp above gives — a file static is one slot for however many corpus threads
       the harness runs, and two healthy runtimes would fold into each other's answer. It is written
       UNCONDITIONALLY, like gc_obj_list and step_census: a field present in one build and not the other makes
       this struct two different sizes, which is the skew that once had two translation units disagree about a
       layout and read a record one slot early. */
    JSGCObjectHeader *gc_decref_parent;
    /* THE POST-COLLECTION SWEEP'S WORKLIST — see js_gc_sweep. It exists because a collection is a phase in
       which some work is unsafe rather than a phase in which nothing may happen: a realm whose last reference
       goes away INSIDE the collection releases its own references there (that half is phase-safe) and parks
       the rest of its teardown here. Held by JSGCObjectHeader.link, which is free to reuse because the header
       is out of gc_obj_list by the time it is on this list. */
    struct list_head gc_ctx_sweep_list;   /* JSContext.header.link — realms whose references are released */
    JSContextTeardownFunc *ctx_teardown;  /* see JS_SetContextTeardownHook */
    JSContextMarkFunc *ctx_mark;          /* see JS_SetContextMarkHook */
    JSGCPhaseEnum gc_phase : 8;
    size_t malloc_gc_threshold;
#ifdef ENABLE_DUMPS // JS_DUMP_LEAKS
    struct list_head string_list; /* list of JSString.link */
#endif
    /* stack limitation */
    uintptr_t stack_size; /* in bytes, 0 if no limit */
    uintptr_t stack_top;
    uintptr_t stack_limit; /* lower stack limit */

    JSValue current_exception;
    /* true if inside an out of memory error, to avoid recursing */
    /* true if inside build_backtrace, to avoid recursing */
    bool in_build_stack_trace;
    /* true if inside JS_FreeRuntime */
    bool in_free;

    struct JSStackFrame *current_stack_frame;

    JSInterruptHandler *interrupt_handler;
    void *interrupt_opaque;

    /* THE ALLOCATOR'S REFUSAL EDGE (quickjs.h's JSMemoryReclaimFunc) and the one-deep latch that keeps it from
       re-entering itself. The callback runs inside a failing allocation and is allowed to free, and freeing can
       allocate (a finalizer, the embedder's own bookkeeping); without the latch that second refusal would ask
       the callback again from inside itself, and the recursion is unbounded on a C stack that cannot be
       parked. One deep is the whole rule: the nested refusal is simply a refusal. */
    JSMemoryReclaimFunc *mem_reclaim;
    void *mem_reclaim_opaque;
    bool in_mem_reclaim;

    JSPromiseHook *promise_hook;
    void *promise_hook_opaque;
    // for smuggling the parent promise from js_promise_then
    // to js_promise_constructor
    JSValueLink *parent_promise;

    JSHostPromiseRejectionTracker *host_promise_rejection_tracker;
    void *host_promise_rejection_tracker_opaque;

    /* HTML 8.1.7's TWO QUEUES, which are not one queue with two kinds of entry in it. `job_list` is the
       MICROTASK queue — promise reactions, queueMicrotask, thenable resolution, dynamic-import continuations.
       `task_list` holds the platform's TASK SOURCES: HTML 8.7 "Timers"'s timer task source, a queued event fire, a
       delivered network reply. The event loop runs ONE task and then performs a MICROTASK CHECKPOINT, which
       drains every microtask — including ones the microtasks themselves enqueue — before the next task begins.
       A single FIFO gets that backwards the moment a task and a microtask are outstanding together, and it did:
       `setTimeout(f, 0)` ran ahead of a promise chain that was already twenty reactions deep, so a transform
       stream's write settled AFTER a `delay(0)` that had to observe it settled. The ordering is not a policy
       this engine picks — it is what the event loop IS — so it lives in the queue rather than in each pump. */
    struct list_head job_list;  /* the MICROTASK queue; list of JSJobEntry.link */
    struct list_head task_list; /* the TASK queues, in the one order a task source's tasks are picked */
    /* THE WORK THE BASELINE QUEUED, WAITING FOR THE FIRST FLOW TO OWN IT — the two queues above answer "what
       does the event loop run next", and this one answers a question that exists before there is an event loop
       at all.
       A DOCUMENT IS CREATED BEFORE ITS AGENT HAS A FRONTIER. HTML §4.8.5's insertion steps run for every
       <iframe> in a document's INITIAL MARKUP, so installing the document queues §7.4 step 14's navigation —
       and in this engine the document is installed by qjs_init while the frontier is seeded by qjs_begin, so
       at that instant there is no flow to own the callback and no scheduler to hand it to. It went on
       `job_list`, which this engine never drains (the scheduler IS the job pump — CLAUDE.md §scheduler), so
       every <iframe src> in a page's own markup was a work item nobody would ever run. The scheduler asserted
       exactly that at the top of its session (engine/host/solver/engine.c), which is why an iframe-bearing page
       ABORTED rather than merely losing its frames.
       SO IT IS HELD HERE AND ADOPTED, which is §Boot's own sentence: the baseline is pre-boot state and boot is
       the forking FIRST FLOW, so work the baseline queued is that flow's. js_adopt_baseline_calls hands the
       whole list to the enqueue hook at the one point a flow is EXECUTING, in arrival order, and the entries
       become ordinary members of the ONE frontier's per-flow queues. Nothing runs from this list: it is a
       handover, not a second pump.
       IT IS NOT `JS_IsJobPending`, DELIBERATELY. That predicate answers "does the runtime hold a job for an
       embedder's JS_ExecutePendingJob to run", and these are not that — no embedder may run them, because the
       callback belongs to a flow's timeline and there is no flow yet. An entry still here when the runtime is
       freed IS a dropped work item, and that is where it crashes.
       EITHER QUEUE'S ENTRIES REACH IT, and each says which it belongs to (JSJobEntry::is_task), because
       ownerlessness is a property of WHEN the user agent queued the callback and not of which queue it named —
       js_enqueue_platform_call carries the counterexample that made the task-only version wrong. */
    struct list_head baseline_call_list; /* list of JSJobEntry.link, both queues' entries in arrival order */
    /* THE NEXT NAME TO ISSUE — see JSTaskHandle in quickjs.h. ONE counter for the whole runtime, so a handle is
       unique across both queues, the baseline list AND whatever the enqueue hook's owner is holding; that
       uniqueness is exactly what JS_RemoveQueuedTask asserts when it refuses to find one handle twice. */
    uint64_t next_task_handle;
    /* FINALIZATION-REGISTRY ENTRIES WHOSE TARGET HAS DIED, waiting to become cleanup jobs. §9.9.4.1's
       HostEnqueueFinalizationRegistryCleanupJob is the HOST's, "at some future time" — V8 posts it from the GC
       epilogue — and this list is that seam. Enqueueing it where the target is freed instead put allocation
       inside object teardown: js_malloc fails, JS_ThrowOutOfMemory throws, the throw frees the previous
       exception, that free runs a finalizer, the finalizer enqueues, and enqueueing allocates. The entries are
       MOVED here rather than copied, so recording one allocates nothing and the references they already hold
       keep the callback and the held value alive exactly as a queued job would. */
    struct list_head finrec_pending; /* list of JSFinRecEntry.link */

    bool module_normalize_has_attr;
    union {
        JSModuleNormalizeFunc *module_normalize_func;
        JSModuleNormalizeFunc2 *module_normalize_func2;
    } normalize_u;
    bool module_loader_has_attr;
    union {
        JSModuleLoaderFunc *module_loader_func;
        JSModuleLoaderFunc2 *module_loader_func2;
    } u;
    JSModuleCheckSupportedImportAttributes *module_check_attrs;
    void *module_loader_opaque;
    /* timestamp for internal use in module evaluation */
    int64_t module_async_evaluation_next_timestamp;

    /* used to allocate, free and clone SharedArrayBuffers */
    JSSharedArrayBufferFunctions sab_funcs;

    bool can_block; /* true if Atomics.wait can block */
    uint32_t dump_flags : 24;

    /* Shape hash table */
    int shape_hash_bits;
    int shape_hash_size;
    int shape_hash_count; /* number of hashed shapes */
    JSShape **shape_hash;
    void *user_opaque;
    void *libc_opaque;
    JSRuntimeFinalizerState *finalizers;
    /* THE PUMP'S PARKED FLOWS — see flow_park. The QUEUE lives on the RUNTIME because that is what it is: each
       parked base owns an async activation belonging to THIS runtime's heap, and resuming one from anywhere
       else frees a frame that another runtime is running. It was a process global with the rt parameter
       accepted and ignored, which made run-test262's worker threads share one: thread A parked its flow,
       thread B's pump resumed it, and the abort surfaced as "async_func_free: freeing a RUNNING async frame"
       in a random test. That made the ONE gate nondeterministic — a DFAIL that fires 3 runs in 4 names
       nothing, and a green run proves nothing either. Per-runtime (not merely per-thread) is the honest
       scope: two runtimes on one thread are just as separate.
       IT HOLDS NO RECORD OF ITS OWN — the record is on the base (JSAsyncFunctionState.park_link), so this is
       ORDER and nothing else. FIFO, which is the ordering-transparency contract stated as a data structure:
       continuations resume in the order they parked, which is the order they would have completed had no
       preempt fired, at any nesting depth and for any number of them. */
    struct list_head parked_flows;   /* JSAsyncFunctionState.park_link, oldest park first */
};

struct JSClass {
    uint32_t class_id; /* 0 means free entry */
    JSAtom class_name;
    JSClassFinalizer *finalizer;
    JSClassGCMark *gc_mark;
    JSClassCall *call;
    /* pointers for exotic behavior, can be NULL if none are present */
    const JSClassExoticMethods *exotic;
};

typedef struct JSStackFrame {
    struct JSStackFrame *prev_frame; /* NULL if first stack frame */
    JSValue cur_func; /* current function, JS_UNDEFINED if the frame is detached */
    JSValue *arg_buf; /* arguments */
    JSValue *var_buf; /* variables */
    struct JSVarRef **var_refs; /* references to arguments or local variables */
    uint8_t *cur_pc; /* only used in bytecode functions : PC of the
                        instruction after the call */
    uint16_t var_ref_count; /* number of var refs */
    uint16_t arg_count;
    bool is_strict_mode;
    bool is_constructor; /* true if invoked as a constructor (new) */
    /* THIS FRAME IS A FLOW'S CALL ROOT, not an activation of anything. A promise reaction's flow base
       (reaction_call_flow_init) holds the handler in cur_func because the handler is what it is about to call —
       but the handler's own activation is a SEPARATE frame pushed on top, so the root is a second frame naming
       the same function, executing no bytecode and holding no program counter. A stack trace that reports it
       prints the handler twice, the second time with no position at all: upstream's walk rendered that as
       "(missing)" behind a FIXME, and the walk that feeds Error.prepareStackTrace subtracted from a null
       pointer and read a line number out of the result. It is not an activation, so it is not a frame. */
    bool is_call_root;
    /* THE BUILTIN WHOSE ACTIVATION INVOKED THIS FRAME, when one did — `Array.prototype.map` for the callback
       it is driving. A continuation-holding builtin is a STEP MACHINE in this engine, and a step machine
       pushes no JSStackFrame of its own: it is driven from the interpreter's activation, so its callback's
       frame is linked straight to the caller and the builtin vanished from every stack trace. V8 reports it
       (`at Array.map`), and it is the truthful answer — the builtin really is on the stack between the two.
       BORROWED from the step state, which outlives every callback it drives. The RECEIVER comes too: the
       builtin's frame is a method call on it, and `map` without it reads as a bare function. */
    JSValueConst step_func, step_this;
    /* THE RECEIVER of this call, BORROWED for the frame's lifetime exactly as cur_func is — the operand stack,
       the heap frame or the coroutine state that holds the callee holds `this` beside it. A stack trace needs
       it: V8's CallSite exposes getThis and getTypeName, and isToplevel is a question ABOUT the receiver
       ("was this called on the global object"), so a frame that does not carry one cannot answer any of them. */
    JSValueConst this_val;
    /* only used in generators. Current stack pointer value. NULL if
       the function is running. */
    JSValue *cur_sp;
    /* THE COLLECTABLE OBJECT THIS FRAME'S STORAGE BELONGS TO, or NULL when nothing the collector can free owns
       it. A SUSPENDED COROUTINE IS LIVE — ECMA-262 §9.4 Execution Contexts: "At some later time a suspended
       execution context may again become the running execution context and continue evaluating its code at the
       point where it had previously been suspended" — but its frame is a HEAP allocation hanging off a GC
       object, not a C activation the collector cannot reach past. A closure that captured one of its locals
       holds an OPEN cell whose storage IS a slot in that allocation, and the cell names the frame by a bare
       pointer: without this field the edge closure -> cell -> coroutine has no counted reference and no mark
       edge, so a coroutine reachable ONLY through such a closure is a cycle to the collector and is freed while
       the closure still points into it. get_captured_cell reads this to decide whether the cell it is about to
       mint must root its owner (see JSVarRef.is_coro).
       NULL IS THE ANSWER FOR EVERY FRAME NOTHING COLLECTABLE OWNS, and that is a positive statement rather than
       an absence: an interpreter activation and a heap-stack TrampFrame are owned by the running flow, a
       JS_FlowNew base and a per-flow generator-data clone are owned by the host and by a COW delta's counted
       reference — none of those can be freed by a collection, so a cell in them needs no root. It is written by
       EVERY constructor of a frame, including the ones that build one field by field (clone_susp_frame's
       callers, reaction_call_flow_init), because a frame whose owner nobody recorded is
       indistinguishable from one that has none. */
    struct JSGCObjectHeader *cur_gc_obj;
} JSStackFrame;

typedef enum {
    JS_GC_OBJ_TYPE_JS_OBJECT,
    JS_GC_OBJ_TYPE_FUNCTION_BYTECODE,
    JS_GC_OBJ_TYPE_SHAPE,
    JS_GC_OBJ_TYPE_VAR_REF,
    JS_GC_OBJ_TYPE_ASYNC_FUNCTION,
    JS_GC_OBJ_TYPE_JS_CONTEXT,
} JSGCObjectTypeEnum;

/* header for GC objects. GC objects are C data structures with a
   reference count that can reference other GC objects. JS Objects are
   a particular type of GC object. */
struct JSGCObjectHeader {
    /* ref_count/gc_obj_type/mark live in the allocator block header (js_rc(p),
       the 8 bytes before every allocation); only the GC list link remains in
       the object body. */
    struct list_head link;
};

typedef struct JSVarRef {
    JSGCObjectHeader header; /* {link}; must come first so &p->header == p */
    uint8_t is_detached;
    uint8_t is_lexical; /* only used with global variables */
    uint8_t is_const; /* only used with global variables */
    /* THIS OPEN CELL ROOTS THE FRAME IT ALIASES. Set at creation for a cell minted in a frame whose storage a
       collectable object owns (JSStackFrame.cur_gc_obj): the cell then holds ONE counted reference to that
       object and is itself a GC object, so the collector can see closure -> cell -> coroutine and cannot free a
       suspended coroutine out from under a closure that captured one of its locals. The owner is recovered as
       stack_frame->cur_gc_obj, which is valid for exactly as long as the cell is open.
       IT IS A SNAPSHOT OF cur_gc_obj != NULL TAKEN AT CREATION, NEVER RE-DERIVED AT READ TIME. cur_gc_obj
       transitions NULL -> owner for a generator and an async generator, whose object does not exist until the
       prologue has run, so a cell minted before that point is not this cell's kind and must not be read as one
       — the ref it never took would be released. async_func_set_owner closes that window by adopting those
       cells at the instant the owner is minted, which is a strictly narrower thing than re-deriving.
       Cleared when the cell detaches; the reference is given back on detach and on free, and on exactly one of
       the two, because a detached cell no longer aliases anything. */
    uint8_t is_coro;
    JSValue *pvalue; /* pointer to the value, either on the stack or
                        to 'value' */
    union {
        JSValue value; /* used when is_detached = true */
        struct {
            uint16_t var_ref_idx; /* index in JSStackFrame.var_refs[] */
            JSStackFrame *stack_frame;
        }; /* used when is_detached = false */
    };
} JSVarRef;

/* Accessors for the reference count and GC mark/type. These fields live in the
   arena block header (the 8 bytes before every allocation, reached via
   js_rc()), not in the object body. The macros yield lvalues, and the argument
   is always the object/header pointer (whose address equals the GC header's,
   since the header is the first member). */
static inline JSMallocBlockHeader *js_rc(const void *p) {
    return (JSMallocBlockHeader *)((uint8_t *)(uintptr_t)p - offsetof(JSMallocBlockHeader, user_data));
}
#define JS_REF_COUNT(p) (js_rc(p)->ref_count)
#define JS_GC_TYPE(p)   (js_rc(p)->gc_obj_type)
#define JS_GC_MARK(p)   (js_rc(p)->mark)

/* bigint */
typedef int32_t js_slimb_t;
typedef uint32_t js_limb_t;
typedef int64_t js_sdlimb_t;
typedef uint64_t js_dlimb_t;

#define JS_LIMB_DIGITS 9

/* Must match the size of short_big_int in JSValueUnion */
#define JS_LIMB_BITS 32
#define JS_SHORT_BIG_INT_BITS JS_LIMB_BITS
#define JS_BIGINT_MAX_SIZE ((1024 * 1024) / JS_LIMB_BITS) /* in limbs */
#define JS_SHORT_BIG_INT_MIN INT32_MIN
#define JS_SHORT_BIG_INT_MAX INT32_MAX


typedef struct JSBigInt {
    uint32_t len; /* number of limbs, >= 1 */
    js_limb_t tab[]; /* two's complement representation, always
                        normalized so that 'len' is the minimum
                        possible length >= 1 */
} JSBigInt;

/* this bigint structure can hold a 64 bit integer */
typedef struct {
    js_limb_t big_int_buf[sizeof(JSBigInt) / sizeof(js_limb_t)]; /* for JSBigInt */
    /* must come just after */
    js_limb_t tab[(64 + JS_LIMB_BITS - 1) / JS_LIMB_BITS];
} JSBigIntBuf;

typedef enum {
    JS_AUTOINIT_ID_PROTOTYPE,
    JS_AUTOINIT_ID_MODULE_NS,
    JS_AUTOINIT_ID_PROP,
} JSAutoInitIDEnum;

/* DELETED: JS_AUTOINIT_ID_BYTECODE and JS_BUILTIN_ARRAY_FROMASYNC. Array.fromAsync was the last self-hosted
   builtin — a compiled JS module read back with JS_ReadObject and EVALUATED FROM C on the first property read,
   which is why the whole of built-ins/Array/fromAsync reported drive-to-completion without fromAsync's own body
   ever appearing in a backtrace. It is now a step machine (js_array_fromasync_def), so nothing reaches this id
   and the eval, the autoinit and the .js/.h pair go with it. */

/* must be large enough to have a negligible runtime cost and small
   enough to call the interrupt callback often. */
#define JS_INTERRUPT_COUNTER_INIT 10000

/* The order is the accessor magic, so a getter is one array read. Paren1..9 are contiguous on purpose. */
enum {
    RE_LEGACY_INPUT, RE_LEGACY_LAST_MATCH, RE_LEGACY_LAST_PAREN,
    RE_LEGACY_LEFT_CONTEXT, RE_LEGACY_RIGHT_CONTEXT,
    RE_LEGACY_PAREN1,
    RE_LEGACY_COUNT = RE_LEGACY_PAREN1 + 9
};

/* HOW MANY DISTINCT ORIGINS ONE REALM'S REFERENCES MAY COME FROM — the width of the per-realm attribution
   below. It is not a bound on anything the engine does: a realm whose references come from more origins than
   this ABORTS in a dev build naming this constant, rather than dropping a row and reporting a breakdown that
   silently does not add up. Raise it; there is nothing to re-derive. */
#define JS_CTX_REF_SITES_MAX 24

struct JSContext {
    JSGCObjectHeader header; /* must come first */
    JSRuntime *rt;
    struct list_head link;

    uint16_t binary_object_count;
    uint32_t binary_object_size : 31;

    /* true if the array prototype is "normal":
       - no small index properties which are get/set or non writable
       - its prototype is Object.prototype
       - Object.prototype has no small index properties which are get/set or non writable
       - the prototype of Object.prototype is null (always true as it is immutable)
    */
    uint8_t std_array_prototype : 1;

    /* THIS REALM'S HALF-TORN-DOWN STATE — see JS_FreeContext. Set by the half that releases every counted
       reference the realm holds, read by the half that frees its tables, so the two cannot run out of order or
       twice however far apart the collector's phase puts them. */
    uint8_t refs_released : 1;

    JSShape *array_shape;   /* initial shape for Array objects */
    JSShape *arguments_shape;  /* shape for arguments objects */
    JSShape *mapped_arguments_shape;  /* shape for mapped arguments objects */
    JSShape *regexp_shape;  /* shape for regexp objects */
    JSShape *regexp_result_shape;  /* shape for regexp result objects */

    JSValue *class_proto;
    /* THE INTRINSIC CONSTRUCTOR OF EACH CLASS, PER REALM — the exact mirror of class_proto, and for the same
       reason §3.7 gives each realm its own prototypes. A spec step that says "! Construct(%DataView%, …)" names
       the INTRINSIC, and the only other way to reach it from C is `class_proto[id].constructor`, which is a
       page-WRITABLE property: a page that assigns `DataView.prototype.constructor = evil` would redirect an
       internal construct that has nothing to do with it. This array is written where the pairing is DEFINED —
       JS_SetConstructor2, the one function that makes an object a class's constructor — so a slot holds what
       the realm was built with and cannot be reached by script.
       It is NOT a named slot beside array_ctor/promise_ctor/regexp_ctor: those are a hand-picked list, and the
       list is exactly what makes a component quietly missing from a realm. */
    JSValue *class_ctor;
    JSValue function_proto;
    JSValue function_ctor;
    JSValue array_ctor;
    JSValue regexp_ctor;
    /* The RegExp Legacy Features proposal's static slots on %RegExp%: [[RegExpInput]], [[RegExpLastMatch]],
       [[RegExpLastParen]], [[RegExpLeftContext]], [[RegExpRightContext]] and [[RegExpParen1]]..[[RegExpParen9]].
       They belong to the INTRINSIC, so there is one set per realm and it lives here. JS_UNINITIALIZED is the
       proposal's `empty`, the state the getters answer with a TypeError — the slots start there and go back
       there whenever a NON-legacy regexp matches. */
    JSValue regexp_legacy[RE_LEGACY_COUNT];
    /* 22.2.7.1 step 4 performs RegExpBuiltinExec DIRECTLY, with no function object to call — and with exec a
       step machine there is nothing to run it from C. This is that algorithm as a callable the engine holds and
       never exposes, so the "call the algorithm" step is the same CALL request every other spelling issues. */
    JSValue regexp_builtin_exec;
    /* 27.1.5.1 CreateAsyncFromSyncIterator ( syncIteratorRecord ) step 3 is `! Get(asyncIterator, "next")` — infallible because the
       object is a hidden intrinsic no page can reach. Performed as a real property read it was still a C-side
       read of JS_ATOM_next, indistinguishable at the call site from a consumer running the iterator protocol
       from C, which is the thing the ratchet exists to keep at zero. The method is the SAME object for every
       wrapper in a realm, so the realm holds it and the AO hands back a complete Iterator Record. */
    JSValue async_from_sync_next;
    JSValue promise_ctor;
    JSValue native_error_proto[JS_NATIVE_ERROR_COUNT];
    JSValue error_ctor;
    /* THE OUT-OF-MEMORY ERROR IS BUILT ONCE, WHILE THERE IS STILL MEMORY. Constructing it at the moment of
       failure is a recursion with a real trigger: the constructor allocates the object, its message string and
       its shape, each of those can fail, and each failure calls JS_ThrowOutOfMemory again. Upstream stops that
       with an `in_out_of_memory` re-entrancy flag, which makes the recursion not happen rather than impossible
       — and it is also what puts every allocation in the engine into one cycle with error construction and,
       through it, with property definition and the GC.
       Pre-allocating is the same thing V8 does with its per-Isolate pre-allocated exceptions, and it costs no
       fidelity here: an OOM error never carried a backtrace anyway (add_backtrace was suppressed by that same
       flag), so the only thing the throw site adds is the throw itself. JS_UNDEFINED where the Error intrinsic
       was never added to this context; the throw then has no object to hand over and says so. */
    JSValue oom_error;
    JSValue error_back_trace;
    /* import(specifier) whose specifier is an OBJECT: 13.3.10.1 runs ToString INSIDE the promise, so an abrupt
       completion REJECTS rather than throws. The capability is created at the opcode and rides the coercion;
       when the coercion throws, the abandon parks it here and the interpreter's exception label — the only place
       that can push the promise as the opcode's RESULT — rejects it once the unwind has returned to the frame
       named in `sf`. NULL whenever no import coercion is in flight. */
    struct JSImportCap *pending_import_cap;
    /* HostLoadImportedModule (16.2.1.10) is ASYNCHRONOUS, and a browser's always is — the module's source comes
       off the network. A loader that cannot answer synchronously calls JS_ModuleLoadPending with a promise that
       settles with the SOURCE TEXT and returns NULL; this is the slot it hands it over in, read by the one
       caller that can wait (JS_LoadModuleInternal) immediately after the loader returns. JS_UNDEFINED whenever
       no load is parked, which is every moment except that handoff. */
    JSValue module_load_pending;
    /* THE RESOLVED SPECIFIER THE PARKED LOAD IS FOR, written by the only function that ever computes it
       (js_host_resolve_imported_module) and taken together with the promise above. The source text alone cannot
       finish a load: compiling it needs this name, which is the record's module map key AND the base every
       specifier inside it resolves against. It used to be dropped and the RAW specifier used in its place, so a
       parked `import("./chunk.js")` registered a record under "./chunk.js" while every lookup asked for the
       resolved name — the same file fetched, compiled and evaluated once per import. */
    JSValue module_load_pending_name;
    /* IfAbruptCloseIterator / IteratorCloseAll deferred to this context's interpreter caller: the JS_CallInternal
       exception label runs 7.4.9 on the tramp for each entry, saving and restoring the in-flight exception across
       it, so the page's `return` (a generator's finally, an accessor, a proxy trap, a plain method containing a
       loop) never runs in a C activation with no flow base. The label picks each route by ITERATOR KIND, the same
       split OP_iterator_close makes — which is why no site that defers one asks what kind it is.
       A STACK rather than a slot, because 7.4.11 IteratorCloseAll closes `in reverse List order`: a site that owes
       SEVERAL pushes them in the order it wants them closed LAST-first, and the drain pops. Six sites used to
       assert the slot was free with the same message naming this exact gap; the queue is that message built. Every
       close under an abrupt completion discards its own throw, which is what makes a whole list drainable in one
       unwind — the completion the drain restores is always the one the first failure raised. */
    JSValue *pending_close_iters;
    int pending_close_n, pending_close_cap;
    /* A KEYED-OPERATION continuation whose unwind only the interpreter can perform, parked by an abandon walk that
       reached it from OUTSIDE the interpreter. The two teardown walks are mutually recursive — getprop_throw and
       do_getprop_abandon hand a CONT_TOPRIM_GET link to js_toprim_abandon, and a coercion requested BY a keyed
       operation (10.4.2.4's two ToPrimitives) hands the link back — but only one of the two is a FUNCTION, so the
       return direction has to be deferred. Every js_toprim_abandon caller goes to the exception label, and that
       label is where the chain is drained into getprop_throw, exactly as the two fields above are drained. NULL
       when idle. */
    void *pending_gp_unwind;
    uint8_t pending_gp_unwind_kind;
    JSValue error_prepare_stack;
    JSValue error_stack_trace_limit;
    JSValue iterator_ctor;
    JSValue iterator_ctor_getset;
    JSValue async_iterator_proto;
    JSValue array_proto_values;
    JSValue throw_type_error;
    /* 16.1 Forbidden Extensions bullet 1 permits a non-strict FunctionDeclaration/FunctionExpression to carry
       own `caller`/`arguments` properties, and that is where the legacy reflection every browser ships lives.
       One accessor pair per realm, installed on each eligible function object. */
    JSValue legacy_reflect_get[2];   /* [0] = caller, [1] = arguments */
    JSValue legacy_reflect_set;
    JSValue eval_obj;

    JSValue global_obj; /* global object */
    JSValue global_var_obj; /* contains the global let/const definitions */

    double time_origin;

    uint64_t random_state;

    /* when the counter reaches zero, JSRutime.interrupt_handler is called */
    int interrupt_counter;

    struct list_head loaded_modules; /* list of JSModuleDef.link */

    /* if NULL, RegExp compilation is not supported */
    JSValue (*compile_regexp)(JSContext *ctx, JSValueConst pattern,
                              JSValueConst flags);
    /* `caller_sf` IS THE OTHER HALF OF `scope_idx`, and both are meaningful only for a DIRECT eval: 13.3.6.1
       evaluates the program in the CALLER's variable environment, so the algorithm needs the caller's frame —
       its bytecode for the strictness, its var_refs for the closure. It is a PARAMETER rather than a read of
       rt->current_stack_frame because on this engine the caller is a HEAP frame: a direct eval is a work item
       on the trampoline's own stack, and §scheduler's rule is that an operation which becomes a work item
       takes its inputs WITH it rather than reading them back off a global that means "the current C
       activation". NULL for every non-direct eval, which is every other caller. */
    /* if NULL, eval is not supported */
    JSValue (*eval_internal)(JSContext *ctx, JSValueConst this_obj,
                             const char *input, size_t input_len,
                             const char *filename, int line, int flags, int scope_idx,
                             JSStackFrame *caller_sf);
    void *user_opaque;
#if APICLIENT_DEV
    /* WHO TOOK EACH OF THIS REALM'S REFERENCES — the per-origin breakdown of the number JS_ContextRefCount
       answers, which states HOW MANY hold a realm and never WHICH edges they are. A census reading only the
       total can say a realm is held by some thousands and name none of them, so a repair has nothing to aim at
       and no way to score itself; core/frame/navigable.h's realm census is the reader this exists for.
       THE ORIGIN IS THE CALLER'S `__func__`, WHICH IS DERIVED AND NEVER A LIST. Every increment of a realm's
       count goes through ONE function, and this file spells that function as a macro that hands the CALLER's
       enclosing function name down — so the set of origins is whatever the code contains and a take site added
       later opens its own row with nothing anywhere to edit. A hand-kept table of who holds a realm would be a
       second copy of a fact the code already states, which is the copy that drifts.
       `__func__` RATHER THAN A `file:line`, because an origin is published and therefore compared across runs:
       a line number renames its own row the first time anything above it is edited, while a function name
       survives that and names the holder better — JS_NewCFunction3 IS "a C function object of this realm",
       JS_DefineAutoInitProperty IS "a lazily built intrinsic property".
       `taken` IS GROSS AND `ref_released_n` IS NOT ATTRIBUTED, because attributing a release means storing the
       origin WITH every reference and a realm's references live in places that have no room for one (a
       bit-packed property slot among them). The breakdown therefore reconciles against the total THROUGH the
       release count rather than being the live attribution, and a reader of a realm whose `released` is
       nonzero is reading gross takes — which the census says in its own output rather than leaving to be
       inferred.
       THE THREE NUMBERS ARE AN IDENTITY AND NOT AN EXPECTATION: JS_NewContextRaw sets the count to 1,
       JS_DupContext is its only increment and JS_FreeContext its only decrement, so
       `1 + ref_taken_n - ref_released_n == JS_REF_COUNT(ctx)` holds at every instant. It is asserted at each
       take and each release, which is what catches a reference taken through a spelling this table never saw —
       including the exported JS_DupContext, which is outside the macro and rows up under its own name. */
    struct { const char *site; int taken; } ref_sites[JS_CTX_REF_SITES_MAX];
    int ref_sites_n;
    int ref_taken_n;
    int ref_released_n;
#endif
};

typedef union JSFloat64Union {
    double d;
    uint64_t u64;
    uint32_t u32[2];
} JSFloat64Union;

typedef enum {
    JS_WEAK_REF_KIND_MAP,
    JS_WEAK_REF_KIND_WEAK_REF,
    JS_WEAK_REF_KIND_FINALIZATION_REGISTRY_ENTRY,
} JSWeakRefKindEnum;

typedef struct JSWeakRefRecord {
    JSWeakRefKindEnum kind;
    struct JSWeakRefRecord *next_weak_ref;
    union {
        struct JSMapRecord *map_record;
        struct JSWeakRefData *weak_ref_data;
        struct JSFinRecEntry *fin_rec_entry;
    } u;
} JSWeakRefRecord;

typedef struct JSMapRecord {
    int ref_count; /* used during enumeration to avoid freeing the record */
    bool empty; /* true if the record is deleted */
    struct JSMapState *map;
    struct list_head link;
    struct list_head hash_link;
    JSValue key;
    JSValue value;
} JSMapRecord;

typedef struct JSMapState {
    bool is_weak; /* true if WeakSet/WeakMap */
    struct list_head records; /* list of JSMapRecord.link */
    uint32_t record_count;
    struct list_head *hash_table;
    uint32_t hash_size; /* must be a power of two */
    uint32_t record_count_threshold; /* count at which a hash table
                                        resize is needed */
} JSMapState;

enum
{
    JS_TO_STRING_IS_PROPERTY_KEY = 1 << 0,
    JS_TO_STRING_NO_SIDE_EFFECTS = 1 << 1,
};

enum {
    JS_ATOM_TYPE_STRING = 1,
    JS_ATOM_TYPE_GLOBAL_SYMBOL,
    JS_ATOM_TYPE_SYMBOL,
    JS_ATOM_TYPE_PRIVATE,
};

enum {
    JS_ATOM_HASH_SYMBOL,
    JS_ATOM_HASH_PRIVATE,
};

typedef enum {
    JS_ATOM_KIND_STRING,
    JS_ATOM_KIND_SYMBOL,
    JS_ATOM_KIND_PRIVATE,
} JSAtomKindEnum;

typedef enum {
    JS_STRING_KIND_NORMAL,
    JS_STRING_KIND_SLICE,
    JS_STRING_KIND_INDIRECT,
} JSStringKind;

#define JS_ATOM_HASH_MASK  ((1 << 28) - 1)

struct JSString {
    uint32_t len : 31;
    uint32_t is_wide_char : 1; /* 0 = 8 bits, 1 = 16 bits characters */
    /* for JS_ATOM_TYPE_SYMBOL: hash = 0, atom_type = 3,
       for JS_ATOM_TYPE_PRIVATE: hash = 1, atom_type = 3
       XXX: could change encoding to have one more bit in hash */
    uint32_t hash : 28;
    uint32_t kind : 2;
    uint32_t atom_type : 2; /* != 0 if atom, JS_ATOM_TYPE_x */
    uint32_t hash_next; /* atom_index for JS_ATOM_TYPE_SYMBOL */
    JSWeakRefRecord *first_weak_ref;
#ifdef ENABLE_DUMPS // JS_DUMP_LEAKS
    struct list_head link; /* string list */
#endif
};

typedef struct JSStringSlice {
    JSString *parent;
    uint32_t start; // in bytes, not characters
} JSStringSlice;

struct JSStringRope {
    uint32_t len;
    uint8_t is_wide_char; /* 0 = 8 bits, 1 = 16 bits characters */
    uint8_t depth;        /* max depth of the rope tree */
    JSValue left;
    JSValue right;        /* might be the empty string */
};

static inline void *strv(JSString *p)
{
    JSStringSlice *slice;
    void **indirect;

    switch (p->kind) {
    case JS_STRING_KIND_NORMAL:
        return (void *)&p[1];
    case JS_STRING_KIND_SLICE:
        slice = (void *)&p[1];
        return (char *)&slice->parent[1] + slice->start;
    case JS_STRING_KIND_INDIRECT:
        indirect = (void *)&p[1];
        return *indirect;
    }
    abort();
    return NULL;
}

static inline uint8_t *str8(JSString *p)
{
    return strv(p);
}

static inline uint16_t *str16(JSString *p)
{
    return strv(p);
}

typedef enum {
    JS_CLOSURE_LOCAL, /* 'var_idx' is the index of a local variable in the parent function */
    JS_CLOSURE_ARG, /* 'var_idx' is the index of an argument variable in the parent function */
    JS_CLOSURE_REF, /* 'var_idx' is the index of a closure variable in the parent function */
    JS_CLOSURE_GLOBAL_REF, /* 'var_idx' is the index of a closure variable in the parent
                              function referencing a global variable */
    JS_CLOSURE_GLOBAL_DECL, /* global variable declaration (eval code only) */
    JS_CLOSURE_GLOBAL, /* global variable (eval code only) */
    JS_CLOSURE_MODULE_DECL, /* definition of a module variable (eval code only) */
    JS_CLOSURE_MODULE_IMPORT, /* definition of a module import (eval code only) */
} JSClosureTypeEnum;

typedef struct JSClosureVar {
    uint8_t closure_type : 3; /* see JSClosureTypeEnum */
    uint8_t is_lexical : 1; /* lexical variable */
    uint8_t is_const : 1; /* const variable (is_lexical = 1 if is_const = 1) */
    uint8_t var_kind : 4; /* see JSVarKindEnum */
    /* 7 bits available */
    uint16_t var_idx; /* JS_CLOSURE_LOCAL/JS_CLOSURE_ARG: index to a normal variable of the
                    parent function. otherwise: index to a closure
                    variable of the parent function */
    JSAtom var_name;
} JSClosureVar;

#define ARG_SCOPE_INDEX 1
#define ARG_SCOPE_END (-2)

/* One provisional Annex B var store: the name it writes, the scope the FunctionDeclaration lives in, and
   where its OP_scope_put_var_env sits in the byte code. `bc_pos` is -1 once the store has been patched out.
   10.2.11 FunctionDeclarationInstantiation step 32.a.i.2.c is the store; its step 32.a.i.2 condition is what
   decides whether the store is made at all, and that is what PROVISIONAL means here. Annex B B.3.2 states the
   feature and no longer states the algorithm: the maintained edition writes these steps inline in 10.2.11 and
   B.3.2 only points at them, which is why no B.3.2.x subsection exists to cite. */
typedef struct JSAnnexBFuncVar {
    JSAtom name;
    int scope_level;
    int bc_pos;
} JSAnnexBFuncVar;

typedef struct JSVarScope {
    int parent;  /* index into fd->scopes of the enclosing scope */
    int first;   /* index into fd->vars of the last variable in this scope */
    uint8_t has_using : 1; /* scope has using declarations */
    int using_label_catch; /* label for catch handler (-1 if none) */
    int using_label_end;   /* label for end of disposal block (-1 if none) */
} JSVarScope;

typedef enum {
    /* XXX: add more variable kinds here instead of using bit fields */
    JS_VAR_NORMAL,
    JS_VAR_FUNCTION_DECL, /* lexical var with function declaration */
    JS_VAR_NEW_FUNCTION_DECL, /* lexical var with async/generator
                                 function declaration */
    JS_VAR_CATCH,
    JS_VAR_FUNCTION_NAME, /* function expression name */
    JS_VAR_PRIVATE_FIELD,
    JS_VAR_PRIVATE_METHOD,
    JS_VAR_PRIVATE_GETTER,
    JS_VAR_PRIVATE_SETTER, /* must come after JS_VAR_PRIVATE_GETTER */
    JS_VAR_PRIVATE_GETTER_SETTER, /* must come after JS_VAR_PRIVATE_SETTER */
    JS_VAR_USING, /* using declaration variable */
    JS_VAR_USING_METHOD, /* hidden local holding the dispose method GetDisposeMethod fetched for one `using`
                            declaration. The pairing lives in fd->using_decls, so this slot is NOT required to sit
                            next to the resource — which is what lets a module-level resource be a var_ref. */
} JSVarKindEnum;

/* XXX: could use a different structure in bytecode functions to save
   memory */
typedef struct JSVarDef {
    JSAtom var_name;
    /* index into fd->scopes of this variable lexical scope */
    int scope_level;
    /* during compilation:
        - if scope_level = 0: scope in which the variable is defined
        - if scope_level != 0: index into fd->vars of the next
          variable in the same or enclosing lexical scope
       in a bytecode function:
       index into fd->vars of the next
       variable in the same or enclosing lexical scope
    */
    int scope_next;
    uint8_t is_const : 1;
    uint8_t is_lexical : 1;
    uint8_t is_captured : 1;
    uint8_t is_static_private : 1; /* only used during private class field parsing */
    uint8_t var_kind : 4; /* see JSVarKindEnum */
    /* if is_captured = true, provides the index of the corresponding
       JSVarRef on stack */
    uint16_t var_ref_idx;
    /* only used during compilation: function pool index for lexical
       variables with var_kind =
       JS_VAR_FUNCTION_DECL/JS_VAR_NEW_FUNCTION_DECL or scope level of
       the definition of the 'var' variables (they have scope_level =
       0) */
    int func_pool_idx; /* only used during compilation : index in
                          the constant pool for hoisted function
                          definition */
} JSVarDef;

/* for the encoding of the pc2line table */
#define PC2LINE_BASE     (-1)
#define PC2LINE_RANGE    5
#define PC2LINE_OP_FIRST 1
#define PC2LINE_DIFF_PC_MAX ((255 - PC2LINE_OP_FIRST) / PC2LINE_RANGE)

typedef enum JSFunctionKindEnum {
    JS_FUNC_NORMAL = 0,
    JS_FUNC_GENERATOR = (1 << 0),
    JS_FUNC_ASYNC = (1 << 1),
    JS_FUNC_ASYNC_GENERATOR = (JS_FUNC_GENERATOR | JS_FUNC_ASYNC),
} JSFunctionKindEnum;

typedef struct JSFunctionBytecode {
    JSGCObjectHeader header; /* must come first */
    uint8_t is_strict_mode : 1;
    uint8_t has_prototype : 1; /* true if a prototype field is necessary */
    uint8_t has_simple_parameter_list : 1;
    uint8_t is_derived_class_constructor : 1;
    /* true if home_object needs to be initialized */
    uint8_t need_home_object : 1;
    uint8_t func_kind : 2;
    uint8_t new_target_allowed : 1;
    uint8_t super_call_allowed : 1;
    uint8_t super_allowed : 1;
    uint8_t arguments_allowed : 1;
    uint8_t backtrace_barrier : 1; /* stop backtrace on this function */
    /* THIS CODE CAME FROM AN eval, which is a property of the SCRIPT and not of the function: a function
       declared inside an eval'd source is eval code too, so the flag rides down the whole nest. V8's
       CallSite#isEval reports it, and its own stack formatter asks before anything else. */
    uint8_t from_eval : 1;
    /* THE TOP-LEVEL PROGRAM ITSELF -- a script, a module, or the body of one eval -- compiled as a function
       because that is how the interpreter runs it, but not an activation of anything the page can name. The
       legacy `f.caller` walk needs to tell it apart from a function DECLARED inside eval code, which carries
       from_eval too and IS a real activation. */
    uint8_t is_program : 1;
    /* HAS A CALL FRAME FOR THIS BODY EVER BEGUN — the one fact an ORPHAN is defined by, and the reason it is a
       bit on the BYTECODE rather than a set kept beside the heap. A function the page DEFINED is a compiled
       body; a closure is one instantiation of it, and a factory called three times makes three closures of one
       body that are one function to anybody reading the source. So the question "did the page ever run this
       code" has exactly one answer per body and it is stored where the body is.
       IT IS SET AT `restart:` AND NOWHERE ELSE. Every way of entering a bytecode body — the C entry, each of
       the trampoline's three pushes, the coroutine resume — converges on that one label before it executes an
       opcode, so a call shape added later cannot forget to mark, because there is no marking to remember. The
       cost is one predictable byte store per frame entry into a struct the interpreter is about to read anyway.
       IT IS ALSO SET BY JS_OrphanTakeOne, which is what makes an orphan a work item taken once rather than a
       question re-asked: see that function for why that is not a seen-set. */
    uint8_t entered : 1;
    /* THIS CODE CAME FROM AN INLINE `<script>` — its source text arrived in the DOCUMENT'S OWN RESPONSE rather
       than in a separately-fetched subresource (HTML §4.12.1 "The script element": `src` "denotes that instead
       of using the element's child text content as the script content, the script will be fetched from the
       specified URL"). Like from_eval it is a property of the SCRIPT and rides down the whole nest, and for the
       same reason it is a bit on the BYTECODE rather than a flag somebody sets around an evaluation: an inline
       script's function can be called back from the bundle an hour of scheduler time later, across parks,
       awaits and flow switches, and the answer must still be the one its SOURCE decides. Its one reader is
       js_document_container_grant, which is where JSObject.doc_built is handed out.
       See JS_EVAL_FLAG_INLINE_SCRIPT for what the two halves are and why they differ. */
    uint8_t from_inline_script : 1;
    /* XXX: 1 bit available */
    uint8_t *byte_code_buf; /* (self pointer) */
    int byte_code_len;
    JSAtom func_name;
    JSVarDef *vardefs; /* arguments + local variables (arg_count + var_count) (self pointer) */
    JSClosureVar *closure_var; /* list of variables in the closure (self pointer) */
    uint16_t arg_count;
    uint16_t var_count;
    uint16_t defined_arg_count; /* for length function property */
    uint16_t stack_size; /* maximum stack size */
    uint16_t var_ref_count; /* number of local variable references */
    uint16_t closure_var_count;
    int cpool_count;
    JSContext *realm; /* function realm */
    JSValue *cpool; /* constant pool (self pointer) */
    JSAtom filename;
    /* WHERE THE eval WAS CALLED, rendered once at compile time — "eval at f (file:12:3)", the string V8's
       CallSite#getEvalOrigin returns. It is the CALLER's position, so it can only be read while that caller is
       still on the stack, which is exactly when the code is being compiled. JS_ATOM_NULL unless from_eval. */
    JSAtom eval_origin;
    int line_num;
    int col_num;
    int source_len;
    int pc2line_len;
    uint8_t *pc2line_buf;
    char *source;
#if APICLIENT_DEV
    /* THE OPERAND DEPTH AT EVERY OPCODE OF THIS BODY — kept instead of thrown away, because it is the only
       thing that can say WHICH opcode left the operand stack at the wrong height.
       compute_stack_size already computes it: its breadth-first walk visits every reachable pc and REFUSES a
       body whose depth at a pc depends on the path that reached it ("inconsistent stack size"). That refusal is
       what makes this a run-time invariant rather than a hint — the depth at a pc is a property of the BYTECODE,
       so the interpreter standing at that pc with any other depth is a defect, not a variation. It is also the
       number the frame is SIZED by, so a runtime that disagrees with it is running on a frame allocated by a
       different rule.
       WHY IT IS NEEDED AT ALL: a shifted operand stack is invisible where it is CREATED and only becomes a crash
       at the next opcode that reads a fixed shape — which can be a whole expression later, in another frame, and
       which then describes a WRONG VALUE rather than a wrong height. §6.2.5's reference-pair assert is exactly
       that: it reports a base and a name, and the reader still has to guess which of the hundreds of pushes and
       pops in between added the slot. This closes that gap by asking at EVERY dispatch, which is the only place
       the question can be universal — a check written at the sites that RESTORE sp is per-spelling plumbing, and
       every spelling it is not written at is a shift nobody is asked about.
       0xffff marks a byte the walk never reached (an operand byte, dead code); NULL means the body came from the
       bytecode READER, which carries `stack_size` on the wire and no per-pc table. */
    uint16_t *stack_level_tab;
#endif
} JSFunctionBytecode;

typedef struct JSBoundFunction {
    JSValue func_obj;
    JSValue this_val;
    int argc;
    JSValue argv[];
} JSBoundFunction;

typedef enum JSIteratorKindEnum {
    JS_ITERATOR_KIND_KEY,
    JS_ITERATOR_KIND_VALUE,
    JS_ITERATOR_KIND_KEY_AND_VALUE,
} JSIteratorKindEnum;

typedef enum JSIteratorHelperKindEnum {
    JS_ITERATOR_HELPER_KIND_DROP,
    JS_ITERATOR_HELPER_KIND_EVERY,
    JS_ITERATOR_HELPER_KIND_FILTER,
    JS_ITERATOR_HELPER_KIND_FIND,
    JS_ITERATOR_HELPER_KIND_FLAT_MAP,
    JS_ITERATOR_HELPER_KIND_FOR_EACH,
    JS_ITERATOR_HELPER_KIND_MAP,
    JS_ITERATOR_HELPER_KIND_SOME,
    JS_ITERATOR_HELPER_KIND_TAKE,
} JSIteratorHelperKindEnum;

typedef struct JSForInIterator {
    JSValue obj;
    bool is_array;
    uint32_t array_length;
    uint32_t idx;
    /* The candidate key whose "was it deleted?" HasProperty is IN FLIGHT (owned), JS_ATOM_NULL otherwise.
       14.7.5.10.2.1 re-checks each key against the object before yielding it, and that check is the page's code —
       a `has` trap on any Proxy in the prototype chain. The check is a request now, so it SUSPENDS, and the
       candidate has to outlive the C frame that chose it. It rides here because the iterator is what the
       operand stack already holds across the suspension, which is why the continuation needs no state of its
       own; the finalizer releases it, so an abandoned flow cannot leak it. */
    JSAtom pending;
} JSForInIterator;

/* THE ARRAY AND STRING ITERATORS' RECORD (hoisted for the time-travel capture, as JSAsyncFromSyncIteratorData is
   for the for-await consumer): ONE struct behind two classes, JS_CLASS_ARRAY_ITERATOR and
   JS_CLASS_STRING_ITERATOR, which is why JS_IterStateSave's arm takes both together.
   ITS MUTABLE HALF IS `obj` AND `idx` AND ITS IMMUTABLE HALF IS `kind`, which is what its time-travel arm is
   built out of: the two constructions write all three and never write them again, and the only writes after
   that are the two `.next()`s advancing `idx` and RELEASING `obj` on exhaustion. */
typedef struct JSArrayIteratorData {
    JSValue obj;   /* the source (an object, or a STRING for JS_CLASS_STRING_ITERATOR); released and set
                      UNDEFINED by the walk that exhausts it, which is what makes it a MUTABLE field */
    JSIteratorKindEnum kind;
    int64_t idx;   /* LengthOfArrayLike is ToLength, so a source can be longer than a uint32 cursor can count */
} JSArrayIteratorData;

typedef struct JSRegExp {
    JSString *pattern;
    JSString *bytecode; /* also contains the flags */
    /* [[LegacyFeaturesEnabled]] (proposal-regexp-legacy-features). True only when %RegExp% itself constructed
       this object — a subclass instance must not be able to write the intrinsic's static slots, which is the
       whole point of the flag: `RegExp.$1` is shared mutable state reachable from any script on the page. */
    bool legacy_features_enabled;
    /* [[Realm]], which RegExpAlloc gives every instance in the same proposal. It exists for exactly one
       comparison — RegExp.prototype.compile refuses a receiver from another realm — and that refusal is the
       same safety argument as the flag: compile REWRITES an existing object's pattern, so a page that could
       reach across realms with it could turn another realm's legacy-enabled regexp into one of its own.
       Owned, like a C function's realm, and marked for the same reason: realm -> instance -> realm is a cycle
       only the GC can break. */
    JSContext *realm;
} JSRegExp;

typedef struct JSProxyData {
    JSValue target;
    JSValue handler;
    uint8_t is_func;
    uint8_t is_revoked;
} JSProxyData;

/* UNKNOWN EXTERNAL INPUT STORED INTO A DATA BLOCK — 10.4.5.18 TypedArraySetElement ( obj, index, value )
   step 3's SetValueInBuffer, for a value no run has determined.
 *
 * THE DATA BLOCK ONLY EVER HOLDS AN EXAMPLE AND THE SPAN IS THE FACT. A block holds uint8_t and not JSValues,
 * so an unknown cannot live in it and converting one would hand the very next read a concrete number where the
 * page had unknown input, deleting the fork and everything behind the other arm. What goes in the block is the
 * unknown's OWN EXAMPLE where it has one — the projection §Solver already asks an unknown for at fetch's URL
 * and the Attr/Element text edges — and the span beside it is what says the bytes are unknown.
 * AND A SPAN IS RECORDED EVEN WHERE NOTHING IS WRITTEN, which is the load-bearing half. An unknown may carry NO
 * example (JSConcolicHooks.example answers JS_UNDEFINED), and there is then no byte to write: inventing one is
 * §@H's value known only to satisfy a gate, one hop worse than inventing `6` for `x > 5`, because a byte in a
 * buffer is INDISTINGUISHABLE from a byte the page computed. So the store leaves the block alone and records
 * the span anyway, and a consumer reading a body whose spans include an exampleless one must refuse to publish
 * it as bytes the page sent — the refusal solver/endpoint.c's body_bytes_b64 already performs for EPB_SHAPE.
 *
 * THE WITNESS IS WHY THERE ARE NO INVALIDATION CALL SITES, AND IT IS THE WHOLE DESIGN. Provenance that shadows
 * MUTABLE bytes goes stale when something overwrites them, and the obvious cure is to drop overlapping spans at
 * every byte write — which is eleven sites (the ones cow_capture_bytes marks: the element store, fill,
 * copyWithin, set's memmove, sort's writeback, reverse, the DataView setters, Atomics) and one silent omission
 * away from a wrong answer. Instead each span records the BYTES STANDING IN THE BLOCK when it was made, and the
 * read compares them: unchanged means nothing has overwritten this element and the unknown still describes it;
 * changed means something did and the span is spent. No writer has to know spans exist.
 * ITS ONE ERROR IS IN THE SAFE DIRECTION, which is why a witness is admissible where over-invalidation is not.
 * A concrete write that happens to store the SAME byte values leaves the span standing, so a read answers with
 * an unknown where the page wrote a concrete byte — it FABRICATES unknownness, and §Solver-half says to err
 * toward MORE exploration because uncertainty keeps the arm. Over-invalidation makes the opposite error: it
 * hands back the example as a concrete number, which is the de-taint this whole record exists to prevent.
 *
 * THE SPANS LIVE IN THE BUFFER'S OWN STORAGE STATE AND NOT IN THE COW SAVE BLOB. A span is a live fact ABOUT
 * these bytes and has to SWAP WITH THEM, so it belongs where the bytes are; JS_BufferStateSave copies it into
 * the baseline alongside `data` and the restore puts the pair back together. That is the same argument the
 * extent, the detached bit and the per-view window are already in ONE entry for — two entries over one buffer
 * have an ORDER in the head and apply replays forward — and JS_BufferStateRestore's immutable DCHECK already
 * tells a future reader to "carry the bit in the buffer-state blob's restore beside the extent", which is this
 * move, anticipated. */
/* A SPAN HAS TWO KINDS BECAUSE 10.4.5.18 READS TWO VALUES THE PAGE SUPPLIES. JS_AB_SPAN_AT is an unknown
   VALUE at a known offset: the block holds its example and the witness decides staleness. JS_AB_SPAN_ANY is a
   write whose OFFSET was unknown — nothing was written anywhere, because there is no offset to write at, and
   the span covers the byte range the offset could have been in.
   THE RANGE IS THE WHOLE BUFFER TODAY AND THAT IS A LIMIT OF THE ENGINE/HOST CONTRACT, NOT A CHOICE. The right
   extent is the offset unknown's own constraint DOMAIN — `for (i = 0; i < 8; i++) buf[i] = x` covers [0,8) and
   leaves byte 9 concrete — and the domain is read by solver/concolic.c's concolic_bound_read, keyed by a hole
   string, which lives in the HOST. The engine reaches the solver only through JSConcolicHooks, whose twenty
   members carry no domain accessor, so an engine-side read of it does not exist to make. Whole-buffer is the
   sound degradation of that and never a cap: it is OVER-GENERAL, which is the direction §Solver-half asks for,
   and it narrows the day a domain hook is added without any other line here changing.
   AN ANY SPAN HAS NO WITNESS, AND THAT IS A STATEMENT RATHER THAN AN OMISSION. A witness answers "has anything
   overwritten the bytes this span describes"; an ANY span describes bytes nothing was written to, so there is
   nothing for a later write to invalidate and no reading of the block that could retire it. It therefore
   stands for the life of the buffer, which is over-general in a second way — a concrete `buf[3] = 7` after an
   unknown-index write still reads unknown at 3 — and that is the same direction and the same reason. */
enum { JS_AB_SPAN_AT = 0, JS_AB_SPAN_ANY };

typedef struct JSArrayBufferSpan {
    uint32_t offset;      /* byte offset into the data block; the START of the covered range for an ANY span */
    uint32_t extent;      /* bytes covered: the element's width for AT, the offset domain's extent for ANY */
    uint8_t kind;         /* JS_AB_SPAN_AT / JS_AB_SPAN_ANY */
    uint8_t witness[8];   /* AT only: the bytes standing in the block when this span was recorded */
    JSValue unknown;      /* the unknown VALUE written, or JS_UNINITIALIZED when an ANY span's value was
                             concrete. ONE COUNTED REFERENCE when set. */
    JSValue index;        /* ANY only: the unknown OFFSET, which is what the read derives from when the value
                             was concrete. ONE COUNTED REFERENCE when set. */
} JSArrayBufferSpan;

typedef struct JSArrayBuffer {
    int byte_length; /* 0 if detached */
    int max_byte_length; /* -1 if not resizable; >= byte_length otherwise */
    uint8_t detached;
    uint8_t immutable;
    uint8_t shared; /* if shared, the array buffer cannot be detached */
    uint8_t *data; /* NULL if detached */
    struct list_head array_list;
    void *opaque;
    JSFreeArrayBufferDataFunc *free_func;
    /* see JSArrayBufferSpan. Empty for every buffer no unknown was ever stored into, which is nearly all of
       them, so the read's cost is one load of a count that is zero. */
    JSArrayBufferSpan *span;
    int n_span;
    int span_size;
} JSArrayBuffer;

typedef struct JSTypedArray {
    struct list_head link; /* link to arraybuffer */
    JSObject *obj; /* back pointer to the TypedArray/DataView object */
    JSObject *buffer; /* based array buffer */
    uint32_t offset; /* byte offset in the array buffer */
    uint32_t length; /* byte length in the array buffer */
    bool track_rab; /* auto-track length of backing array buffer */
} JSTypedArray;

/* How a flow base COMPLETES — an explicit frame-KIND on the base, dispatched at ONE point, mirroring
   TimeTravelJS's tt_frame_kind. Without it, completion was inferred from the base's bytecode (b->func_kind),
   which a BODYLESS base (a call-root over a step closure, cur_func not bytecode) cannot answer — forcing a
   b==NULL hack. The kind makes the bodyless case first-class: its entry dispatches through do_step_tramp and its
   completion settles through its own arm, never touching b. */
enum {
    FLOW_BASE_BYTECODE = 0,   /* cur_func is a bytecode function; entry/completion use its b (the default) */
    FLOW_BASE_STEP_ROOT,      /* cur_func is a STEP CLOSURE; the flow's whole body is one call handler(arg) */
    /* cur_func is bytecode, but this state is EMBEDDED IN a JSAsyncFunctionData whose promise its completion
       settles (js_async_function_call). Entry and completion are BYTECODE's; what differs is ownership, and the
       one thing that must know is the snapshot FORK — a clone of this base is a bare state with no
       JSAsyncFunctionData behind it, so its completion has no promise to settle and the original's data is freed
       from under it. */
    FLOW_BASE_ASYNC_CALL,
};
/* …AND HOW THIS SITE'S CONTINUATION FORKS, declared beside the resume and the disposer and required of every
   site for the same reason the disposer is required: a flow's suspension has TWO HOMES — the program frame the
   scheduler holds, and the parked continuation of a job, which is the home a flow has while it is between
   programs — and a fork of a flow suspended in the second must give the arm a continuation OF ITS OWN.
   ONE PARK PER ARM, NEVER ONE SHARED: flow_clone_state_alloc states the invariant from the other end (a clone
   is BORN UNPARKED) because a park is one activation's ONE resume point, so handing one record to two arms
   resumes one activation twice and the second resume rebuilds a frame the first already freed.
   WHAT ONLY THE SITE KNOWS is which handle its own resume and disposer take — the base for a reaction, the
   JSAsyncFunctionData for an async call, the generator OBJECT for an async-generator body, which the park
   record already keeps apart from the base precisely because they are not the same thing. `clone` is the base
   JS_FlowClone built; the site answers with the handle for it, having taken whatever reference the new park
   owns on it.
   THE TAG IS DECLARED AT FILE SCOPE FIRST, and that line is not decoration: a struct tag first named inside a
   prototype's parameter list has PROTOTYPE scope, so it would be a different incomplete type from the struct
   defined below and every site would be passing an incompatible pointer. */
struct JSAsyncFunctionState;
typedef void *JSFlowParkCloneFn(JSContext *ctx, void *opaque, struct JSAsyncFunctionState *clone);
typedef struct JSAsyncFunctionState {
    JSValue this_val; /* 'this' generator argument */
    int argc; /* number of function arguments */
    bool throw_flag; /* used to throw an exception in JS_CallInternal() */
    uint8_t base_kind; /* FLOW_BASE_* — how this base enters and completes (see the enum above) */
    JSStackFrame frame;
    void *tramp_top;  /* APIClient forced-exec: the stashed heap-frame (TrampFrame) chain when this flow was
                         PREEMPTED mid-execution at depth; NULL when suspended at the base or not suspended. */
    /* THE PARK — see flow_park. A parked continuation is a property of THE BASE IT SUSPENDS and of nothing
       else: it re-enters this activation, under this activation's heap, and no other base can be handed it.
       It used to be one struct on the JSRuntime, which is a CAPACITY where the design has none — the number
       of continuations parked before the pump next runs is the number of bases a step reaches, and that is
       unbounded in both directions. SEQUENTIALLY: one host drain settles several fetch replies in a row and
       each settle is its own call-root flow, so reply A's resolve parked and reply B's park had nowhere to
       go. NESTED: an async body's completion settles its promise through a second call-root flow while the
       reaction that resumed it is still live on the C stack, and both can park. Neither is a bigger version
       of the one-slot case; the slot simply could not represent them, and what it did instead was assert.
       The link is INTRUSIVE and lives in the base rather than in a node the park allocates, for two reasons
       that are the same reason: a park may not fail (an OOM here would DROP a work item, which §NO BOUNDS
       forbids), and a base that is already queued has nowhere to be queued twice — so "one flow parked
       twice" stops being a rule someone keeps and becomes a shape that cannot be built.
       `park_ctx` is recorded rather than derived because the resume runs in the realm that parked.
       `park_fn` IS THE AUTHORITY ON WHETHER THIS BASE IS PARKED, and `park_link` means nothing at all while it
       is NULL. That is not a convenience, it is what makes a base UNPARKED BY CONSTRUCTION: every allocator in
       this file hands out zeroed bytes, list_add_tail WRITES both link pointers without reading them, and
       list_del's own fail-safe leaves a detached node at {NULL,NULL} — so zero, freshly-detached and
       deliberately-cleared are ONE state and nothing has to be remembered to reach it.
       IT WAS WRITTEN THE OTHER WAY FIRST AND THAT COST A FALSE ABORT. The asserts read `list_empty(&park_link)`,
       which is a HEAD predicate (`el->next == el`) and answers FALSE for the {NULL,NULL} a zeroed or detached
       node holds — so every base built by a constructor that did not self-link the field read as parked. The
       per-flow clone of an async activation is allocated from zeroed bytes and does not self-link, so an
       ordinary async body that had never parked in its life aborted at its own teardown. Asking `park_fn` is both the
       true question and the one no constructor can get wrong by omission. */
    struct list_head park_link;     /* on JSRuntime.parked_flows while park_fn != NULL; meaningless otherwise */
    JSFlowParkFn *park_fn;          /* NULL iff not parked — THE authority; park_link is then unread */
    JSFlowParkFreeFn *park_free_fn; /* how this site gives its reference back without running the body */
    JSFlowParkCloneFn *park_clone_fn; /* how this site's continuation FORKS — see the typedef above */
    void *park_opaque;
    JSContext *park_ctx;
} JSAsyncFunctionState;

/* XXX: could use an object instead to avoid the
   JS_TAG_ASYNC_FUNCTION tag for the GC */
typedef struct JSAsyncFunctionData {
    JSGCObjectHeader header; /* must come first */
    JSValue resolving_funcs[2];
    bool is_active; /* true if the async function state is valid */
    JSAsyncFunctionState func_state;
} JSAsyncFunctionData;

typedef enum JSGeneratorStateEnum {
    JS_GENERATOR_STATE_SUSPENDED_START,
    JS_GENERATOR_STATE_SUSPENDED_YIELD,
    JS_GENERATOR_STATE_SUSPENDED_YIELD_STAR,
    JS_GENERATOR_STATE_EXECUTING,
    JS_GENERATOR_STATE_COMPLETED,
} JSGeneratorStateEnum;

typedef struct JSGeneratorData {
    JSGeneratorStateEnum state;
    /* cow_ref: 0 = the ORIGINAL gen_data, owned by its generator object (freed by js_generator_finalizer);
       >0 = a per-flow CLONE produced by a concolic fork inside the body (clone_deep_flow), owned by that many
       COW deltas (JS_GenDataRef/Unref), freed at 0. The generator OBJECT is shared across a fork; only its
       u.generator_data POINTER is swapped per-flow (a COW gendata entry), so each arm advances its own state. */
    int cow_ref;
    JSAsyncFunctionState func_state;
} JSGeneratorData;

#define GEN_MAGIC_NEXT   0
#define GEN_MAGIC_RETURN 1
#define GEN_MAGIC_THROW  2

typedef struct JSReqModuleEntry {
    JSAtom module_name;
    JSModuleDef *module; /* used using resolution */
    JSValue attributes; /* JS_UNDEFINED or an object containing the attributes as key/value */
} JSReqModuleEntry;

typedef enum JSExportTypeEnum {
    JS_EXPORT_TYPE_LOCAL,
    JS_EXPORT_TYPE_INDIRECT,
} JSExportTypeEnum;

typedef struct JSExportEntry {
    union {
        struct {
            int var_idx; /* closure variable index */
            JSVarRef *var_ref; /* if != NULL, reference to the variable */
        } local; /* for local export */
        int req_module_idx; /* module for indirect export */
    } u;
    JSExportTypeEnum export_type;
    /* `export * as ns from "m"`. It used to be spelled by setting local_name to the atom for "*", which IS a
       legal ModuleExportName -- a module may `export {x as "*"}` -- so a program using that name collided with
       the engine's own marker and its import resolved to the namespace object. The marker is a property of the
       ENTRY, not a value in the user's name space. */
    bool is_namespace;
    JSAtom local_name; /* the imported name for an indirect export; meaningless when is_namespace */
    JSAtom export_name; /* exported variable name */
} JSExportEntry;

typedef struct JSStarExportEntry {
    int req_module_idx; /* in req_module_entries */
} JSStarExportEntry;

typedef struct JSImportEntry {
    int var_idx; /* closure variable index */
    bool is_namespace; /* `import * as ns from "m"` — see JSExportEntry.is_namespace */
    JSAtom import_name; /* meaningless when is_namespace */
    int req_module_idx; /* in req_module_entries */
} JSImportEntry;

typedef enum {
    JS_MODULE_STATUS_UNLINKED,
    JS_MODULE_STATUS_LINKING,
    JS_MODULE_STATUS_LINKED,
    JS_MODULE_STATUS_EVALUATING,
    JS_MODULE_STATUS_EVALUATING_ASYNC,
    JS_MODULE_STATUS_EVALUATED,
} JSModuleStatus;

struct JSModuleDef {
    JSAtom module_name;
    struct list_head link;

    JSReqModuleEntry *req_module_entries;
    int req_module_entries_count;
    int req_module_entries_size;

    JSExportEntry *export_entries;
    int export_entries_count;
    int export_entries_size;

    JSStarExportEntry *star_export_entries;
    int star_export_entries_count;
    int star_export_entries_size;

    JSImportEntry *import_entries;
    int import_entries_count;
    int import_entries_size;

    JSValue module_ns;
    JSValue func_obj; /* only used for JS modules */
    JSModuleInitFunc *init_func; /* only used for C modules */
    bool has_tla; /* true if func_obj contains await */
    /* 16.2.1.5's [[Status]] `new`, INVERTED: false means this record's requested modules have never been
       loaded. The spec gives `new` its own status because loading and linking are different phases with
       different failure semantics — a load that FAILS leaves every record it touched still `new`, so a later
       load walks the graph again, while a load that SUCCEEDS moves them all to `unlinked` together at the very
       end (16.2.1.6.1.1.1 step 5.b). `status` below starts at UNLINKED and cannot express `new`, so this bool
       is it, and it is written in exactly one place: the completion of a load. It used to mean "this walk has
       reached this module", set on the way IN, which conflated `new` with the per-load [[Visited]] set — and a
       graph whose child load failed was then never walked again, so its unanswered request reached Link. */
    bool loaded;
    bool func_created;
    JSModuleStatus status : 8;
    /* temp use during js_module_link() & js_module_evaluate() */
    int dfs_index, dfs_ancestor_index;
    JSModuleDef *stack_prev;
    /* temp use during js_module_evaluate() */
    JSModuleDef **async_parent_modules;
    int async_parent_modules_count;
    int async_parent_modules_size;
    int pending_async_dependencies;
    bool async_evaluation;
    int64_t async_evaluation_timestamp;
    JSModuleDef *cycle_root;
    /* Has this module's EVALUATION been started? It used to be inferred from `promise != undefined`, which
       stopped being the same fact once a consumer could take the capability BEFORE evaluating (so it could
       register its continuation ahead of a fork inside the body). Inferred, a dynamic import of an
       already-EVALUATED module — whose evaluation created no capability of its own, because only a cycle root
       gets one — was read as "in flight" and handed back an undefined promise that nothing would ever settle. */
    bool eval_started;
    JSValue promise; /* corresponds to spec field: capability */
    JSValue resolving_funcs[2]; /* corresponds to spec field: capability */
    /* true if evaluation yielded an exception. It is saved in
       eval_exception */
    bool eval_has_exception;
    JSValue eval_exception;
    JSValue meta_obj; /* for import.meta */
    JSValue private_value; /* private value for C modules */
};

typedef struct JSJobEntry {
    struct list_head link;
    JSContext *ctx;
    JSJobFunc *job_func;
    int argc;
    /* WHICH OF HTML 8.1.7'S TWO QUEUES THIS ENTRY BELONGS TO. On `job_list`/`task_list` the list it is on is
       already the answer; on `baseline_call_list` there is no such list to read it off, and the adoption has to
       hand the scheduler the same flag js_enqueue would have — so a task the user agent queued before the
       frontier existed does not arrive as a microtask and run inside the first checkpoint it meets. */
    bool is_task;
    /* THIS ENTRY'S NAME — the same one the enqueue answered its caller and the same one the enqueue hook was
       offered, so an entry that starts on the baseline list and is later adopted by a flow keeps it. Without
       that, a tracker holding a handle across the handover would name nothing the instant the frontier began. */
    JSTaskHandle handle;
    JSValue argv[];
} JSJobEntry;

typedef struct JSProperty {
    union {
        JSValue value;      /* JS_PROP_NORMAL */
        struct {            /* JS_PROP_GETSET */
            JSObject *getter; /* NULL if undefined */
            JSObject *setter; /* NULL if undefined */
        } getset;
        JSVarRef *var_ref;  /* JS_PROP_VARREF */
        struct {            /* JS_PROP_AUTOINIT */
            /* in order to use only 2 pointers, we compress the realm
               and the init function pointer */
            uintptr_t realm_and_id; /* realm and init_id (JS_AUTOINIT_ID_x)
                                       in the 2 low bits */
            void *opaque;
        } init;
    } u;
} JSProperty;

#define JS_PROP_INITIAL_SIZE 2
#define JS_PROP_INITIAL_HASH_SIZE 4 /* must be a power of two */

typedef struct JSShapeProperty {
    uint32_t hash_next : 26; /* 0 if last in list */
    uint32_t flags : 6;   /* JS_PROP_XXX */
    JSAtom atom; /* JS_ATOM_NULL = free property entry */
} JSShapeProperty;

struct JSShape {
    /* hash table of size hash_mask + 1 before the start of the
       structure (see prop_hash_end()). */
    JSGCObjectHeader header;
    /* true if the shape is inserted in the shape hash table. If not,
       JSShape.hash is not valid */
    uint8_t is_hashed;
    uint32_t hash; /* current hash value */
    uint32_t prop_hash_mask;
    int prop_size; /* allocated properties */
    int prop_count; /* include deleted properties */
    int deleted_prop_count;
    JSShape *shape_hash_next; /* in JSRuntime.shape_hash[h] list */
    JSObject *proto;
    uint32_t hash_table[]; /* prop_hash_mask + 1 elements, then prop[prop_size] */
};

/* The two ShadowRealm slot carriers, up here because JS_GetFunctionRealm reads a wrapped function's
   [[Realm]] and the object union names both. Their operations live with the rest of the membrane. */
typedef struct JSShadowRealmData {
    JSContext *realm;   /* [[ShadowRealm]] */
} JSShadowRealmData;

typedef struct JSWrappedFunctionData {
    JSValue target;     /* [[WrappedTargetFunction]] */
    JSContext *realm;   /* [[Realm]] — the realm this wrapper belongs to; its caller's */
} JSWrappedFunctionData;

struct JSObject {
    /* ref_count/gc_obj_type/mark live in the allocator block header; the object
       body keeps only the GC list link plus the object's own flags. */
    JSGCObjectHeader header; /* {link}; must come first so &p->header == p */
    uint8_t is_prototype : 1; /* object may be used as prototype */
    uint8_t extensible : 1;
    uint8_t free_mark : 1; /* only used when freeing objects with cycles */
    uint8_t is_exotic : 1; /* true if object has exotic property handlers */
    uint8_t fast_array : 1; /* true if u.array is used for get/put (for JS_CLASS_ARRAY, JS_CLASS_ARGUMENTS, JS_CLASS_MAPPED_ARGUMENTS and typed arrays) */
    uint8_t is_constructor : 1; /* true if object is a constructor function */
    uint8_t is_uncatchable_error : 1; /* if true, error is not catchable */
    uint8_t tmp_mark : 1; /* used in JS_WriteObjectRec() */
    uint8_t is_HTMLDDA : 1; /* specific annex B IsHtmlDDA behavior */
    /* APIClient forced-exec: THE DOCUMENT'S OWN BYTES WROTE THIS CONTAINER'S EXTENT — the half of the page the
       server re-renders for every request decided which members exist — so the extent was chosen against THIS
       VISITOR'S CREDENTIALS rather than by the program.
       THAT IS ONE OF THE CHANNEL'S TWO QUESTIONS AND NOT BOTH OF THEM, which is why this bit is read through
       two predicates. It decides whether the publication walk may DESCEND through the container and NAME what
       is inside it, and a LIST answers it yes. Whether a member the container does not hold is the server's
       SILENCE — unknown rather than `undefined` — is the other question, and a list answers that one no
       (§10.4.2 Array Exotic Objects: its `length` is greater than every own index, so the document that wrote
       the list said how long it is). The first question is js_object_is_document_container's and the second
       is js_object_is_document_record's; one bit answering both is what left every record inside a server
       dump's lists unreachable.
       IT IS GRANTED, NEVER INFERRED, and js_document_container_grant is the one place that grants it. Read that
       function for why the fact is the EXTENT'S AUTHOR and not the allocation: this bit used to be set by the
       object ALLOCATOR for any ordinary object born while an inline script was somewhere on the stack, which
       is a proxy that answers the same for `window.gon={}` and for `new Event("go")` — and a platform object
       on this channel answers a member Web IDL DEFINES with an unknown, silently. */
    uint8_t doc_built : 1;
    /* …AND IT IS REACHABLE FROM THE GLOBAL through such records, so the server PUBLISHED it: it is
       on the one channel a server has into a bundle it ships to everybody unchanged, and a member it does not
       hold is unknown rather than `undefined`. Set by js_publish_document_namespace, which is also what tells
       the host the PATH the record is read by. Both bits only ever go 0 -> 1: they are PROVENANCE, so they are
       immutable once true and need no COW capture — a fork inherits what was already true when it happened,
       and an arm that publishes a shared record states a fact the other arm's document is equally entitled to.
       See JSConcolicHooks.publish for the channel these are the two ends of. */
    uint8_t doc_namespace : 1;
    uint16_t class_id; /* see JS_CLASS_x */
    /* APIClient forced-exec: the FORK GENERATION at which this object was created (0 = baseline, pre-flow). An
       object is SHARED with a snapshot-forked sibling iff it existed at that flow's fork (flow_gen <= the flow's
       fork_gen); an object created AFTER the fork (flow_gen > fork_gen) is flow-PRIVATE and its writes are never
       captured — the load-bearing invariant that keeps a per-flow delta O(shared-state-touched), not O(transients).
       A single "have I forked" bit could not tell a pre-fork shared object from a post-fork private one, so it
       over-captured every post-fork transient; the generation distinguishes them. */
    uint32_t flow_gen;
    /* byte offsets: 16/24 */
    JSShape *shape; /* prototype and property names + flag */
    JSProperty *prop; /* array of properties */
    /* byte offsets: 24/40 */
    JSWeakRefRecord *first_weak_ref;
    /* byte offsets: 28/48 */
    union {
        void *opaque;
        struct JSBoundFunction *bound_function; /* JS_CLASS_BOUND_FUNCTION */
        struct JSCFunctionDataRecord *c_function_data_record; /* JS_CLASS_C_FUNCTION_DATA */
        struct JSCClosureRecord *c_closure_record; /* JS_CLASS_C_CLOSURE */
        struct JSForInIterator *for_in_iterator; /* JS_CLASS_FOR_IN_ITERATOR */
        struct JSArrayBuffer *array_buffer; /* JS_CLASS_ARRAY_BUFFER, JS_CLASS_SHARED_ARRAY_BUFFER */
        struct JSTypedArray *typed_array; /* JS_CLASS_UINT8C_ARRAY..JS_CLASS_DATAVIEW */
        struct JSMapState *map_state;   /* JS_CLASS_MAP..JS_CLASS_WEAKSET */
        struct JSMapIteratorData *map_iterator_data; /* JS_CLASS_MAP_ITERATOR, JS_CLASS_SET_ITERATOR */
        struct JSArrayIteratorData *array_iterator_data; /* JS_CLASS_ARRAY_ITERATOR, JS_CLASS_STRING_ITERATOR */
        struct JSRegExpStringIteratorData *regexp_string_iterator_data; /* JS_CLASS_REGEXP_STRING_ITERATOR */
        struct JSGeneratorData *generator_data; /* JS_CLASS_GENERATOR */
        struct JSIteratorConcatData *iterator_concat_data; /* JS_CLASS_ITERATOR_CONCAT */
        struct JSIteratorZipData *iterator_zip_data; /* JS_CLASS_ITERATOR_ZIP */
        struct JSIteratorHelperData *iterator_helper_data; /* JS_CLASS_ITERATOR_HELPER */
        struct JSIteratorWrapData *iterator_wrap_data; /* JS_CLASS_ITERATOR_WRAP */
        struct JSProxyData *proxy_data; /* JS_CLASS_PROXY */
        struct JSShadowRealmData *shadow_realm_data; /* JS_CLASS_SHADOW_REALM */
        struct JSWrappedFunctionData *wrapped_function_data; /* JS_CLASS_WRAPPED_FUNCTION */
        struct JSPromiseData *promise_data; /* JS_CLASS_PROMISE */
        struct JSPromiseFunctionData *promise_function_data; /* JS_CLASS_PROMISE_RESOLVE_FUNCTION, JS_CLASS_PROMISE_REJECT_FUNCTION */
        struct JSAsyncFunctionData *async_function_data; /* JS_CLASS_ASYNC_FUNCTION_RESOLVE, JS_CLASS_ASYNC_FUNCTION_REJECT */
        struct JSAsyncFromSyncIteratorData *async_from_sync_iterator_data; /* JS_CLASS_ASYNC_FROM_SYNC_ITERATOR */
        struct JSAsyncGeneratorData *async_generator_data; /* JS_CLASS_ASYNC_GENERATOR */
        struct { /* JS_CLASS_BYTECODE_FUNCTION: 12/24 bytes */
            /* also used by JS_CLASS_GENERATOR_FUNCTION, JS_CLASS_ASYNC_FUNCTION and JS_CLASS_ASYNC_GENERATOR_FUNCTION */
            struct JSFunctionBytecode *function_bytecode;
            JSVarRef **var_refs;
            JSObject *home_object; /* for 'super' access */
        } func;
        struct { /* JS_CLASS_C_FUNCTION: 12/20 bytes */
            JSContext *realm;
            JSCFunctionType c_function;
            uint8_t length;
            uint8_t cproto;
            /* THE SECOND CARRIER of a machine id, for the builtins that cannot spell one in `magic` — and the
               only builtins in that position are CONSTRUCTORS. There is ONE id namespace (the ITERCONS_* /
               NATIVE_* block by JSIterConsume); what differs is where a callee writes its id down. An ordinary
               builtin writes it in `magic` and says so in `cproto` (JS_CFUNC_STEP_DEF, JS_CFUNC_CONSUME_DEF); a
               constructor cannot, because its cproto is spent saying "constructor" and its magic IS the class id
               or the STEPDEF id its create-from-ctor machine runs on. Map and TypedArray each declare BOTH — a
               create machine in `magic` and a consume walk here — because 24.1.1.1 and 23.2.5.1 are single
               algorithms whose ARGUMENT chooses between two continuations, and the dispatch's arms ask that
               argument question. 0 = this callee declares no machine here.
               It is NOT a pointer in JSCFunctionType, which holds function pointers only (data there is the
               strict-aliasing violation that passes at -O0 and segfaults at -O1). It costs nothing: this struct
               is 20 bytes inside a 24-byte union.
               It is not a fallback selector and never was: what a read of it picks between is several algorithms
               the SPEC distinguishes, and the C bodies those arms decline to are DFAILs or the argument branches
               that invoke nothing (24.1.1.1 step 4's empty collection, 23.2.5.1 step 6.b's view over a buffer,
               27.5.3.1 step 2's non-callable executor). Deleting any of those leaves the field still needed to
               say WHICH machine runs — which is the test that separates routing from a fallback. */
            uint8_t native_machine;
            /* THIS BODY RUNS NONE OF THE PAGE'S CODE — the C-function twin of JSClassExoticMethods'
               get_own_property_no_user_code, and it exists for the same reason and is read at the same kind of
               seam. A property READ that lands on an accessor cannot invoke it from C, because §10.1.8.1
               OrdinaryGet ( obj, propertyKey, receiver ) step 7's `Return ? Call(getter, receiver)` is the
               PAGE'S function and a C activation has no flow base under it — a loop in that body would drive to
               completion. That reasoning is about a body that RUNS THE PAGE, and it is VACUOUS for a C getter
               that runs none: there is no continuation to hold, nothing to preempt, and the routed path calls
               the identical C function through the identical js_call_c_function.
               0 = UNDECLARED, which is the default and stays the default: an undeclared getter reached from C
               is a read that must be routed and the accessor arm crashes naming it. Only a body whose author
               DECLARED this is answered directly, and the declaration is FALSIFIED at runtime — see
               js_no_user_code_enter and the assert at JS_CallInternal's bytecode dispatch, which is the one
               door the page's code comes through. It is not a list of exempt function pointers and not a
               predicate at the read: a new getter is undeclared until its own install line says otherwise, and
               a declared one that later gains a route to the page aborts at the frame that proves it.
               It is one byte in this struct's existing tail padding — 20 bytes inside a 24-byte union either
               way, exactly as native_machine above. */
            uint8_t no_user_code;
            int16_t magic;
        } cfunc;
        /* array part for fast arrays and typed arrays */
        struct { /* JS_CLASS_ARRAY, JS_CLASS_ARGUMENTS, JS_CLASS_MAPPED_ARGUMENTS, JS_CLASS_UINT8C_ARRAY..JS_CLASS_FLOAT64_ARRAY */
            union {
                uint32_t size;          /* JS_CLASS_ARRAY */
                struct JSTypedArray *typed_array; /* JS_CLASS_UINT8C_ARRAY..JS_CLASS_FLOAT64_ARRAY */
            } u1;
            union {
                JSValue *values;        /* JS_CLASS_ARRAY, JS_CLASS_ARGUMENTS */
                JSVarRef **var_refs;    /* JS_CLASS_MAPPED_ARGUMENTS */
                void *ptr;              /* JS_CLASS_UINT8C_ARRAY..JS_CLASS_FLOAT64_ARRAY */
                int8_t *int8_ptr;       /* JS_CLASS_INT8_ARRAY */
                uint8_t *uint8_ptr;     /* JS_CLASS_UINT8_ARRAY, JS_CLASS_UINT8C_ARRAY */
                int16_t *int16_ptr;     /* JS_CLASS_INT16_ARRAY */
                uint16_t *uint16_ptr;   /* JS_CLASS_UINT16_ARRAY */
                int32_t *int32_ptr;     /* JS_CLASS_INT32_ARRAY */
                uint32_t *uint32_ptr;   /* JS_CLASS_UINT32_ARRAY */
                int64_t *int64_ptr;     /* JS_CLASS_INT64_ARRAY */
                uint64_t *uint64_ptr;   /* JS_CLASS_UINT64_ARRAY */
                uint16_t *fp16_ptr;     /* JS_CLASS_FLOAT16_ARRAY */
                float *float_ptr;       /* JS_CLASS_FLOAT32_ARRAY */
                double *double_ptr;     /* JS_CLASS_FLOAT64_ARRAY */
            } u;
            uint32_t count; /* <= 2^31-1. 0 for a detached typed array */
        } array;    /* 12/20 bytes */
        JSRegExp regexp;    /* JS_CLASS_REGEXP: 8/16 bytes */
        JSValue object_data;    /* for JS_SetObjectData(): 8/16/16 bytes */
    } u;
    /* byte sizes: 40/48/72 */
};

typedef struct JSCallSiteData {
    JSValue filename;
    JSValue func;
    JSValue func_name;
    JSValue this_val;   /* the frame's RECEIVER: getThis, getTypeName and isToplevel are all about it */
    JSValue eval_origin; /* JS_NULL unless is_eval: the compile-time rendering of where the eval was called */
    bool native;
    bool is_eval;       /* this code, or the code it is nested in, came from an eval */
    bool constructor;
    bool strict;        /* a strict frame does not hand its receiver or its function to a stack formatter */
    int line_num;
    int col_num;
} JSCallSiteData;

