                local_buf = gtf->caller_local_buf; stack_buf = gtf->caller_stack_buf;
                var_buf = gtf->caller_var_buf; arg_buf = gtf->caller_arg_buf;
                this_obj = gtf->caller_this; new_target = gtf->caller_new_target;
                var_refs = gtf->caller_var_refs;
