                        gp_recv = tg->recv; gp_no_throw = tg->no_throw; gp_desc_out = tg->desc_out;
                        gp_getter = tg->getter; gp_setter = tg->setter; gp_dflags = tg->dflags;
                        gp_outer = tg->outer; gp_outer_kind = tg->outer_kind;
                        gp_trapst = tg;
