                            gd->obj = js_dup(gp->value);
                            gd->target = js_dup(pd5->target);
                            gd->trap_res = ret_val;        /* held across steps 10 and 12 */
                            gd->atom = JS_DupAtom(ctx, gp->atom);
                            gd->outer = gouter; gd->outer_kind = gouter_kind;
                            gd->desc_out = gp->desc_out;
