JSValue JS_NewDate(JSContext *ctx, double epoch_ms)
{
    JSValue obj = js_create_from_intrinsic(ctx, JS_CLASS_DATE);
    if (JS_IsException(obj))
        return JS_EXCEPTION;
    JS_SetObjectData(ctx, obj, js_float64(time_clip(epoch_ms)));
    return obj;
}

bool JS_IsDate(JSValueConst v)
{
    if (JS_VALUE_GET_TAG(v) != JS_TAG_OBJECT)
        return false;
    return JS_VALUE_GET_OBJ(v)->class_id == JS_CLASS_DATE;
}

double JS_GetDateValue(JSValueConst v)
{
    JSObject *p;

    DCHECK(JS_IsDate(v), "a [[DateValue]] was read off something that is not a Date — JS_IsDate is how a "
                         "caller finds that out, and an object of another class has no such slot");
    p = JS_VALUE_GET_OBJ(v);
    DCHECK(JS_IsNumber(p->u.object_data), "a Date's [[DateValue]] is not a number — the slot is set to a "
                                          "time-clipped double at construction and never to anything else");
    /* An integral time value is stored with the INT tag by the float constructor's own normalisation, so both
       tags are the one slot and reading only the float half would answer garbage for `new Date(0)`. */
    return JS_VALUE_GET_TAG(p->u.object_data) == JS_TAG_INT ? (double)JS_VALUE_GET_INT(p->u.object_data)
                                                            : JS_VALUE_GET_FLOAT64(p->u.object_data);
}

int JS_AddIntrinsicDate(JSContext *ctx)
{
    JSValue obj;

    obj = JS_NewCConstructor(ctx, JS_CLASS_DATE, "Date",
                             NULL, 7, JS_CFUNC_step_ctor, STEPDEF_DATE_CTOR,
                             JS_UNDEFINED,
                             js_date_funcs, countof(js_date_funcs),
                             js_date_proto_funcs, countof(js_date_proto_funcs),
                             0);
    if (JS_IsException(obj))
        return -1;
    JS_FreeValue(ctx, obj);
    return 0;
}

/* eval */

int JS_AddIntrinsicEval(JSContext *ctx)
{
#ifndef QJS_DISABLE_PARSER
    ctx->eval_internal = __JS_EvalInternal;
#endif // QJS_DISABLE_PARSER
    return 0;
}

/* BigInt */

static JSValue JS_ToBigIntCtorFree(JSContext *ctx, JSValue val)
{
    uint32_t tag;

 redo:
    tag = JS_VALUE_GET_NORM_TAG(val);
    switch(tag) {
    case JS_TAG_INT:
    case JS_TAG_BOOL:
        val = JS_NewBigInt64(ctx, JS_VALUE_GET_INT(val));
        break;
    case JS_TAG_SHORT_BIG_INT:
    case JS_TAG_BIG_INT:
        break;
    case JS_TAG_FLOAT64:
        {
            double d = JS_VALUE_GET_FLOAT64(val);
            JSBigInt *r;
            int res;
            r = js_bigint_from_float64(ctx, &res, d);
            if (!r) {
                if (res == 0) {
                    val = JS_EXCEPTION;
                } else if (res == 1) {
                    val = JS_ThrowRangeError(ctx, "cannot convert to BigInt: not an integer");
                } else {
                    val = JS_ThrowRangeError(ctx, "cannot convert NaN or Infinity to BigInt");                }
            } else {
                val = JS_CompactBigInt(ctx, r);
            }
        }
        break;
    case JS_TAG_STRING:
    case JS_TAG_STRING_ROPE:
        val = JS_StringToBigIntErr(ctx, val);
        break;
    case JS_TAG_OBJECT:
        val = JS_ToPrimitiveFree(ctx, val, HINT_NUMBER);
        if (JS_IsException(val))
            break;
        goto redo;
    case JS_TAG_NULL:
    case JS_TAG_UNDEFINED:
    default:
        JS_FreeValue(ctx, val);
        return JS_ThrowTypeError(ctx, "cannot convert to BigInt");
    }
    return val;
}

static JSValue js_bigint_constructor(JSContext *ctx,
                                     JSValueConst new_target,
                                     int argc, JSValueConst *argv)
{
    if (!JS_IsUndefined(new_target))
        return JS_ThrowTypeErrorNotAConstructor(ctx, new_target);
    return JS_ToBigIntCtorFree(ctx, js_dup(argv[0]));
}

static JSValue js_thisBigIntValue(JSContext *ctx, JSValueConst this_val)
{
    if (JS_IsBigInt(this_val))
        return js_dup(this_val);

    if (JS_VALUE_GET_TAG(this_val) == JS_TAG_OBJECT) {
        JSObject *p = JS_VALUE_GET_OBJ(this_val);
        if (p->class_id == JS_CLASS_BIG_INT) {
            if (JS_IsBigInt(p->u.object_data))
                return js_dup(p->u.object_data);
        }
    }
    return JS_ThrowTypeError(ctx, "not a BigInt");
}

static JSValue js_bigint_toString(JSContext *ctx, JSValueConst this_val,
                                  int argc, JSValueConst *argv)
{
    JSValue val;
    int base;
    JSValue ret;

    val = js_thisBigIntValue(ctx, this_val);
    if (JS_IsException(val))
        return val;
    if (argc == 0 || JS_IsUndefined(argv[0])) {
        base = 10;
    } else {
        base = js_get_radix(ctx, argv[0]);
        if (base < 0)
            goto fail;
    }
    ret = js_bigint_to_string1(ctx, val, base);
    JS_FreeValue(ctx, val);
    return ret;
 fail:
    JS_FreeValue(ctx, val);
    return JS_EXCEPTION;
}

static JSValue js_bigint_valueOf(JSContext *ctx, JSValueConst this_val,
                                 int argc, JSValueConst *argv)
{
    return js_thisBigIntValue(ctx, this_val);
}

static JSValue js_bigint_asUintN(JSContext *ctx,
                                  JSValueConst this_val,
                                  int argc, JSValueConst *argv, int asIntN)
{
    uint64_t bits;
    JSValue res, a;

    if (JS_ToIndex(ctx, &bits, argv[0]))
        return JS_EXCEPTION;
    a = JS_ToBigInt(ctx, argv[1]);
    if (JS_IsException(a))
        return JS_EXCEPTION;
    if (bits == 0) {
        JS_FreeValue(ctx, a);
        res = __JS_NewShortBigInt(ctx, 0);
    } else if (JS_VALUE_GET_TAG(a) == JS_TAG_SHORT_BIG_INT) {
        /* fast case */
        js_slimb_t sv = JS_VALUE_GET_SHORT_BIG_INT(a);
        if (bits >= JS_SHORT_BIG_INT_BITS && (asIntN || sv >= 0)) {
            res = a;
        } else if (bits < JS_SHORT_BIG_INT_BITS) {
            uint64_t v;
            int shift;
            shift = 64 - bits;
            v = sv;
            v = v << shift;
            if (asIntN)
                v = (int64_t)v >> shift;
            else
                v = v >> shift;
            res = __JS_NewShortBigInt(ctx, v);
        } else {
            JSBigInt *r;
            uint64_t len64 = (bits + JS_LIMB_BITS - 1) / JS_LIMB_BITS;
            int len, shift, i;

            if (len64 > JS_BIGINT_MAX_SIZE) {
                JS_FreeValue(ctx, a);
                return JS_ThrowRangeError(ctx, "BigInt is too large to allocate");
            }
            len = len64;
            r = js_bigint_new(ctx, len);
            if (!r) {
                JS_FreeValue(ctx, a);
                return JS_EXCEPTION;
            }
            r->len = len;
            r->tab[0] = sv;
            for(i = 1; i < len; i++)
                r->tab[i] = -1;
            shift = (-bits) & (JS_LIMB_BITS - 1);
            r->tab[len - 1] = (r->tab[len - 1] << shift) >> shift;
            r = js_bigint_extend(ctx, r, 0);
            JS_FreeValue(ctx, a);
            if (!r)
                return JS_EXCEPTION;
            res = JS_CompactBigInt(ctx, r);
        }
    } else {
        JSBigInt *r, *p = JS_VALUE_GET_PTR(a);
        int is_neg = js_bigint_sign(p);
        if (bits >= (uint64_t)p->len * JS_LIMB_BITS &&
            (asIntN || !is_neg)) {
            res = a;
        } else {
            uint64_t len64 = (bits + JS_LIMB_BITS - 1) / JS_LIMB_BITS;
            int len, shift, i;
            js_limb_t v;
            if (len64 > JS_BIGINT_MAX_SIZE) {
                JS_FreeValue(ctx, a);
                return JS_ThrowRangeError(ctx, "BigInt is too large to allocate");
            }
            len = len64;
            r = js_bigint_new(ctx, len);
            if (!r) {
                JS_FreeValue(ctx, a);
                return JS_EXCEPTION;
            }
            r->len = len;
            for(i = 0; i < len - 1; i++)
                r->tab[i] = i < p->len ? p->tab[i] : -is_neg;
            shift = (-bits) & (JS_LIMB_BITS - 1);
            /* 0 <= shift <= JS_LIMB_BITS - 1 */
            v = (len - 1 < p->len ? p->tab[len - 1] : -is_neg) << shift;
            if (asIntN)
                v = (js_slimb_t)v >> shift;
            else
                v = v >> shift;
            r->tab[len - 1] = v;
            if (!asIntN)
                r = js_bigint_extend(ctx, r, 0);
            if (!r) {
                JS_FreeValue(ctx, a);
                return JS_EXCEPTION;
            }
            r = js_bigint_normalize(ctx, r);
            JS_FreeValue(ctx, a);
            res = JS_CompactBigInt(ctx, r);
        }
    }
    return res;
}

